}

return [null, dbMsg, { payload: '스케줄 실행(제어없음): ' + rule.name }, null, null];

// ================================================================
// ⑤-A 스케줄 실행 준비 (Modbus 상태 읽기 요청)
// ================================================================
// ★ 2026-06-04 race fix — flow.set('pendingRule') 제거
//   옛 패턴: 같은 시각 2 rule 발동 시 두 번째가 첫 번째 덮어쓰기 → 첫 rule 미실행
//   신: msg._scheduledRule + msg._scheduledActions 직접 보관 (각 메시지 독립)

var rule = msg.scheduledRule;
var actions = msg.scheduledActions;

if (!rule || !actions || actions.length === 0) {
