            }
        }
    }
});

var firstUnitId = parseInt(Object.keys(unitIds)[0]) || 1;

// ★ 모듈 등록 정보 (Settings → 릴레이 모듈 관리) 의 channels 동적 사용
var relayModulesList = (houseConfig.settings && houseConfig.settings.relayModules) || [];
var moduleEntry = relayModulesList.find(function(m) { return Number(m.unitId) === firstUnitId; });
var quantity = Number(moduleEntry && moduleEntry.channels) || 8;

msg.payload = {
    value: msg.payload,
