    fc: 1,
    address: 0,
    quantity: quantity
};

msg.topic = 'schedule_precheck';

node.warn('🔍 스케줄 사전 확인: unitId=' + firstUnitId + ' Modbus 읽기 (rule=' + rule.name + ')');
return msg;

var farmId = env.get('FARM_ID') || global.get('FARM_ID') || global.get('farmId') || 'farm_0001';
msg.url = 'https://api.smartgreen.kr/api/automation/' + farmId;
