        return null;
    }

    const atMs = Date.now() + delaySec * 1000;
    const offReqId = `sched-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const baseMsg = RED.util.cloneMessage(msg);

    const timerId = setTimeout(function () {
