            node.warn(`⏰ 예약 만료 → OFF: ${key}`);

            const moduleType = savedModbus.moduleType || 'waveshare';
            const unitId = savedModbus.unitId || 1;
            const address = savedModbus.address;
            const address2 = savedModbus.address2;
            const controlType = savedModbus.controlType || 'single';

            let offPayload;
            if (moduleType === 'eletechsup') {
                offPayload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: 0x0200 };
            } else {
                if (controlType === 'bidir') {
                    offPayload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [false, false] };
                } else {
                    offPayload = { fc: 15, unitid: unitId, address: address, quantity: 1, value: [false] };
                }
            }

            const offMsg = {
                topic: baseMsg.topic || `smartfarm/${farmId || ''}/${houseId}/${deviceId}/control`,
                payload: offPayload,
                _isLastWrite: true,
                _requestId: offReqId,
                control: {
                    farmId,
                    houseId,
                    deviceId,
                    command: 'off',
                    operator: 'schedule_off_timer',
                    requestId: offReqId,
                    timestamp: new Date().toISOString(),
                    modbus: savedModbus,
                },
            };

            global.set('_pendingModbus', { requestId: offReqId, isLastWrite: true });
            // ★ 출력 1 (execute_control 로) 발사 — modbus-flex-write 까지 도달
            node.send([offMsg, null, null]);

            node.status({ fill: 'blue', shape: 'dot', text: `예약 OFF 실행 ${key}` });

            // deviceStates 업데이트 — 다중 하우스: houseId 포함 키
            const dkeyOff = global.get('dkey') || function (h, dv) { return (h || 'house_0001') + ':' + dv; };
            const DKOFF = dkeyOff(houseId, deviceId);
            const dStates = global.get('deviceStates') || {};
            if (controlType === 'bidir') {
                dStates[DKOFF] = 'closed';
                const dPositions = global.get('devicePositions') || {};
                dPositions[DKOFF] = 0;
                global.set('devicePositions', dPositions);
            } else {
                dStates[DKOFF] = 'off';
            }
            global.set('deviceStates', dStates);

            // cleanup
            const s = global.get('scheduledOff') || {};
            delete s[key];
            global.set('scheduledOff', s);
        } catch (e) {
            node.error(`❌ schedule-off setTimeout 콜백 에러: ${e.message}\n${e.stack}`);
        }
    }, delaySec * 1000);

    sched[key] = {
        atMs,
        timerId,
        deviceId,
        houseId,
        farmId,
        modbus: savedModbus,
        scheduledAt: new Date().toISOString(),
        scheduledBy: payload.operator || 'unknown',
    };
    global.set('scheduledOff', sched);

    const min = Math.round(delaySec / 60);
    const atStr = new Date(atMs).toLocaleTimeString('ko-KR', { hour12: false });
    node.warn(`📅 예약 등록: ${key} — ${min}분 후 OFF (${atStr})`);
    node.status({ fill: 'yellow', shape: 'dot', text: `예약 ${key} ${min}분` });
    return null;
}

// ============================================================
// 일반 제어 (on/off/open/close/stop)
// ============================================================
let deviceType = 'unknown';
if (deviceId.startsWith('window')) deviceType = 'window';
else if (deviceId.startsWith('fan')) deviceType = 'fan';
else if (deviceId.startsWith('heater')) deviceType = 'heater';
else if (deviceId.startsWith('valve')) deviceType = 'valve';

msg.control = {
    farmId,
    houseId,
    deviceId,
    deviceType,
    command,
    operator,
    requestId,
    timestamp,
    raw: payload
};

const cmdLabels = { open: '열기', close: '닫기', stop: '정지', on: 'ON', off: 'OFF' };
const label = cmdLabels[command] || command;
const fIdLabel = farmId ? `${farmId}/` : '';

node.status({
    fill: 'green',
    shape: 'dot',
    text: `${label} ← ${fIdLabel}${houseId}/${deviceId} (${operator})`
});

node.warn(`📥 제어 수신: ${fIdLabel}${houseId}/${deviceId} ${command.toUpperCase()} by ${operator} [${requestId}]`);

return msg;

// ============================================================
// "제어 실행 (릴레이)" (execute_control) — KS X 3267 분기 추가본 (2026-08-30 P3)
// 위치: NR 에디터 "AWS IoT 제어 수신" 탭 → "제어 실행 (릴레이)" 노드
// 적용: 코드 전체 교체 + **출력 개수 2 → 3** + 3번 출력을 새 link out("→ KS3267 명령")에 연결
// 변경: (1) modbus.protocol==='ks3267' 이면 3번 출력으로 (vendor 경로 무수정)
//       (2) 모든 return/node.send 를 3-슬롯으로 (1·2번 출력 동작 동일)
// ============================================================
// Modbus 릴레이 제어 — Waveshare FC15 (8CH coil) only
// 출력 1: Modbus Flex Write
// 출력 2: MQTT out (장치 위치 보고)
//
// ★ 2026-06-03 근본 단순화 + MUTEX 패치
//   - eletechsup 분기 제거 — 메모리: 2026-05-08 HW 제거됨 (MEMORY.md "Modbus 릴레이 제어")
//   - default unitId 1→2 (Waveshare default, 옛 unitId 하드코딩 사고 패턴 제거)
//   - write 발사 직전 _modbusLastWriteAt 갱신 → "제어 후 상태 발행"이 SAFE_GAP_MS(500ms)
//     후 read 발사 → RS-485 single bus 의 write-read race 차단
const ctrl = msg.control || {};
const pl = msg.payload || {};
var modbus = pl.modbus || msg.modbus || ctrl.modbus;
const command = ctrl.command || pl.command || 'stop';
const duration = ctrl.duration || pl.duration || 0;

const deviceId = ctrl.deviceId || pl.deviceId || pl.window_id || pl.device_id || 'unknown';
const reqId = msg._requestId || null;

// -- 다중 하우스: 장치 키 --------------------------------
// 장치 ID 는 하우스 안에서만 유일하므로 (house_0001/fan1, house_0002/fan1)
// 장치 단위 전역 키는 반드시 houseId 를 포함해야 한다.
const houseId = ctrl.houseId || pl.houseId || 'house_0001';
const dkey = global.get('dkey') || function (h, dv) { return (h || 'house_0001') + ':' + dv; };

node.warn('📦 수신 duration=' + duration + ' command=' + command + ' deviceId=' + deviceId);

// === 장치 상태 기록 함수 ===
function saveDeviceState(devId, cmd, cType, msgDuration) {
    var DK = dkey(houseId, devId);
    var states = global.get('deviceStates') || {};
    if (cType === 'bidir') {
        var positions = global.get('devicePositions') || {};
        var moves = global.get('movements') || {};
        if (cmd === 'open' || cmd === 'close') {
            states[DK] = cmd === 'open' ? 'open' : 'closed';
            var startPosNow = positions[DK] !== undefined ? positions[DK] : (cmd === 'open' ? 0 : 100);
            moves[DK] = { startedAt: Date.now(), startPos: startPosNow, command: cmd };
            global.set('movements', moves);
            var modbusCfgStart = global.get('modbus_cfg_' + DK);
            var fullDurStart = modbusCfgStart ? (cmd === 'open' ? modbusCfgStart.openDuration : modbusCfgStart.closeDuration) : 0;
            var actualDurStart, targetPosStart;
            if (msgDuration && msgDuration > 0 && fullDurStart > 0 && msgDuration < fullDurStart) {
                actualDurStart = msgDuration;
                var deltaPctStart = Math.round(100 * msgDuration / fullDurStart);
                targetPosStart = cmd === 'open'
                    ? Math.min(100, startPosNow + deltaPctStart)
                    : Math.max(0, startPosNow - deltaPctStart);
                if (targetPosStart >= 95) targetPosStart = 100;
                if (targetPosStart <= 5) targetPosStart = 0;
            } else {
                var remainRatioStart = cmd === 'open' ? (100 - startPosNow) / 100 : startPosNow / 100;
                actualDurStart = fullDurStart > 0 ? Math.max(1, Math.round(fullDurStart * remainRatioStart)) : 0;
                targetPosStart = cmd === 'open' ? 100 : 0;
            }
            var fidStart = global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';
            node.send([null, {
                topic: 'smartfarm/' + fidStart + '/device/position',
                payload: JSON.stringify({
                    houseId: houseId,
                    deviceId: devId,
                    position: startPosNow,
                    command: cmd,
                    startPosition: startPosNow,
                    targetPosition: targetPosStart,
                    duration: actualDurStart,
                    startedAt: new Date().toISOString()
                })
            }, null]);
        } else if (cmd === 'stop') {
            var move = moves[DK];
            var modbusCfg = global.get('modbus_cfg_' + DK);
            var newPos = positions[DK] !== undefined ? positions[DK] : 0;
            if (move && move.startedAt && modbusCfg) {
                var elapsed = (Date.now() - move.startedAt) / 1000;
                var fullDur = move.command === 'open' ? modbusCfg.openDuration : modbusCfg.closeDuration;
                if (fullDur > 0) {
                    var deltaPctStop = Math.round(100 * Math.min(elapsed, fullDur) / fullDur);
                    if (move.command === 'open') {
                        newPos = Math.min(100, move.startPos + deltaPctStop);
                    } else {
                        newPos = Math.max(0, move.startPos - deltaPctStop);
                    }
                    if (newPos <= 5) newPos = 0;
                    if (newPos >= 95) newPos = 100;
                    positions[DK] = newPos;
                    global.set('devicePositions', positions);
                    node.warn('📍 Duration 위치 계산: ' + devId + ' ' + move.startPos + '% → ' + newPos + '% (' + elapsed.toFixed(1) + 's / ' + fullDur + 's)');
                }
            }
            if (newPos === 100) states[DK] = 'open';
            else if (newPos === 0) states[DK] = 'closed';
            else states[DK] = 'idle';
            delete moves[DK];
            global.set('movements', moves);
            var fid = global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';
            node.send([null, {
                topic: 'smartfarm/' + fid + '/device/position',
                payload: JSON.stringify({ houseId: houseId, deviceId: devId, position: newPos, command: 'stop' })
            }, null]);
        }
    } else {
        if (cmd === 'on' || cmd === 'open') states[DK] = 'on';
        else states[DK] = 'off';
    }
    global.set('deviceStates', states);
}

// === MQTT 위치 보고 함수 ===
function reportPosition(devId, pos) {
    var farmId = global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';
    node.send([null, {
        topic: 'smartfarm/' + farmId + '/device/position',
        payload: JSON.stringify({ houseId: houseId, deviceId: devId, position: pos, command: 'stop' })
    }, null]);
    node.warn('📍 MQTT 위치 보고: ' + farmId + '/' + houseId + '/' + devId + ' → ' + pos + '%');
}

// === duration 자동 정지 함수 (Waveshare FC15) ===
function scheduleAutoStop(devId, uId, addr, dur, cmd) {
    if (dur <= 0) return;
    var DK2 = dkey(houseId, devId);
    var timerKey = 'autoStop_' + DK2;
    var existing = global.get(timerKey);
    if (existing) clearTimeout(existing);

    var timer = setTimeout(function() {
        // Waveshare FC15 — bidir 두 coil 한 번에 OFF
        var stopMsg = RED.util.cloneMessage(msg);
        stopMsg.payload = { fc: 15, unitid: uId, address: addr, quantity: 2, value: [false, false] };
        global.set('_modbusLastWriteAt', Date.now());   // ★ MUTEX (자동정지)
        node.send([stopMsg, null, null]);
        global.set(timerKey, null);

        // 위치 갱신 — 부분 동작 vs 한계까지 구분
        var positions = global.get('devicePositions') || {};
        var moves = global.get('movements') || {};
        var move = moves[DK2];
        var modbusForCalc = global.get('modbus_cfg_' + DK2);
        var newPos;
        if (modbusForCalc && (cmd === 'open' || cmd === 'close')) {
            var fullDurCalc = cmd === 'open' ? (modbusForCalc.openDuration || 0) : (modbusForCalc.closeDuration || 0);
            if (fullDurCalc > 0 && dur > 0 && dur < fullDurCalc) {
                var startPosCalc = (move && typeof move.startPos === 'number') ? move.startPos : (cmd === 'open' ? 0 : 100);
                var deltaPctCalc = Math.round(100 * dur / fullDurCalc);
                if (cmd === 'open') newPos = Math.min(100, startPosCalc + deltaPctCalc);
                else newPos = Math.max(0, startPosCalc - deltaPctCalc);
                if (newPos >= 95) newPos = 100;
                if (newPos <= 5) newPos = 0;
            } else {
                newPos = (cmd === 'open') ? 100 : 0;
            }
        } else {
            newPos = (cmd === 'open') ? 100 : 0;
        }
        positions[DK2] = newPos;
        global.set('devicePositions', positions);
        delete moves[DK2];
        global.set('movements', moves);
        saveDeviceState(devId, 'stop', 'bidir');
        reportPosition(devId, positions[DK2]);
        node.warn('⏱️ 자동 정지: ' + DK2 + ' (' + dur + '초) → 위치: ' + positions[DK2] + '%');
        node.status({ fill: 'grey', shape: 'ring', text: '자동 정지: ' + devId + ' ' + positions[DK2] + '%' });
    }, dur * 1000);

    global.set(timerKey, timer);
    node.warn('⏱️ 자동 정지 예약: ' + devId + ' → ' + dur + '초 후');
}

// === Modbus 설정 캐시 ===
if (modbus) {
    global.set('modbus_cfg_' + dkey(houseId, deviceId), modbus);
} else {
    modbus = global.get('modbus_cfg_' + dkey(houseId, deviceId));
    if (modbus) {
        node.warn('[Modbus] ' + deviceId + ': 캐시에서 modbus 설정 로드');
    }
}

flow.set('lastControl', { deviceId: deviceId, command: command, houseId: houseId });

// ━━━ KS X 3267 표준 노드 → 별도 탭으로 (P3, 2026-08-30) ━━━
// houseConfig 의 modbus 프로필이 { protocol:'ks3267', unit, kind, n } 이면 Waveshare 경로를 타지 않고
// 3번 출력(link out → "KS X 3267 표준노드" 탭)으로 넘긴다. vendor 경로는 아래 그대로.
if (modbus && modbus.protocol === 'ks3267') {
    msg.control = Object.assign({}, ctrl, { houseId: houseId, deviceId: deviceId, command: command, duration: duration, modbus: modbus });
    node.status({ fill: 'blue', shape: 'dot', text: 'KS3267 → ' + deviceId + ' ' + command });
    return [null, null, msg];
}

if (!modbus || modbus.address === null || modbus.address === undefined) {
    node.warn('[Modbus] ' + deviceId + ': modbus 설정 없음 — 무시');
    node.status({ fill: 'yellow', shape: 'ring', text: deviceId + ': modbus 미설정' });
    return null;
}

// unitId default 2 (Waveshare) — 미설정 시 경고 후 default 적용
if (!modbus.unitId) {
    node.warn('⚠️ [Modbus] ' + deviceId + ': unitId 미설정 — Waveshare default uid:2 적용');
}
const unitId = modbus.unitId || 2;
const controlType = modbus.controlType || 'single';
const address = modbus.address;
const address2 = modbus.address2;

node.warn('[Modbus] waveshare uid:' + unitId + ' ' + deviceId + ' ' + command + ' (' + controlType + ') duration=' + duration);

// stop 명령 시 기존 자동 정지 타이머 취소
if (command === 'stop') {
    var timerKey = 'autoStop_' + dkey(houseId, deviceId);
    var existing = global.get(timerKey);
    if (existing) {
        clearTimeout(existing);
        global.set(timerKey, null);
        node.warn('⏱️ 자동 정지 취소: ' + deviceId + ' (수동 정지)');
    }
}

// Waveshare FC15 — bidir 2채널 또는 single 1채널
if (controlType === 'bidir') {
    if (command === 'open') {
        msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [true, false] };
        node.status({ fill: 'green', shape: 'dot', text: 'FC15 열기: uid' + unitId + ' ch' + address });
    } else if (command === 'close') {
        msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [false, true] };
        node.status({ fill: 'green', shape: 'dot', text: 'FC15 닫기: uid' + unitId + ' ch' + address2 });
    } else {
        msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [false, false] };
        node.status({ fill: 'grey', shape: 'dot', text: 'FC15 정지: ALL OFF' });
    }
} else {
    var on = (command === 'on' || command === 'open');
    msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 1, value: [on] };
    node.status({ fill: 'green', shape: 'dot', text: 'FC15 uid' + unitId + ' ch' + address + '=' + (on ? 'ON' : 'OFF') });
}
global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
saveDeviceState(deviceId, command, controlType, duration);
if (controlType === 'bidir' && (command === 'open' || command === 'close')) {
    scheduleAutoStop(deviceId, unitId, address, duration, command);
}
global.set('_modbusLastWriteAt', Date.now());   // ★ MUTEX
return [msg, null, null];

// ============================================================
// "응답 메시지 생성" (send_ack) — 100농장 표준화 Phase B (옛 호환 제거)
//
// 위치: NR 에디터 "AWS IoT 제어 수신" 탭의 "응답 메시지 생성" 노드 (id: send_ack)
// 적용:
//   1. NR 에디터 → 탭 "AWS IoT 제어 수신" → "응답 메시지 생성" 더블클릭
//   2. 기존 코드 백업 후 이 파일 내용으로 교체
//   3. Deploy
//
// Phase B 변경:
//   - 옛 4-seg 응답 fallback 제거
//   - farmId 가 없으면 farmId='unknown' fallback (절대 발생하지 말아야 함 — 경고 로그)
//   - 새 5-seg 응답 토픽 (smartfarm/{farmId}/{houseId}/{deviceId}/response) 만 발행
// ============================================================

const { farmId, houseId, deviceId, command, requestId, operator } = msg.control;

// Phase B: farmId 필수. 없으면 경고 + fallback
const effectiveFarmId = farmId || env.get('FARM_ID') || 'unknown';
if (!farmId) {
    node.warn(`⚠ send_ack: msg.control.farmId 없음 (옛 클라이언트?) — env FARM_ID 사용: ${effectiveFarmId}`);
}

msg.topic = `smartfarm/${effectiveFarmId}/${houseId}/${deviceId}/response`;

msg.payload = {
    request_id: requestId,
    farm_id: effectiveFarmId,
    house_id: houseId,
    device_id: deviceId,
    command: command,
    status: 'received',
    operator: operator,
    executed_at: new Date().toISOString(),
    device_client: env.get('NR_MQTT_CLIENT_ID') || 'MyFarmPi_unknown',
};

node.status({
    fill: 'blue',
    shape: 'dot',
    text: `응답 → ${msg.topic}`
});

return msg;

// Modbus Write 성공 응답이면 무시 (출력2에도 성공 메시지가 옴)
if (msg.queueUnitId !== undefined) {
    node.status({ fill: 'green', shape: 'dot', text: '성공 — 무시' });
    return null;
}
var lastCtrl = flow.get('lastControl') || {};
var deviceId = lastCtrl.deviceId || 'unknown';
var command = lastCtrl.command || 'unknown';
var houseId = lastCtrl.houseId || '';

var errorMsg = msg.payload?.error || msg.error?.message || 'Modbus Write 실패';

node.warn('⚡ 제어 실패: ' + deviceId + ' (' + command + ') - ' + errorMsg);

msg = {
    payload: {
        alarm_type: 'CONTROL_FAILURE',
        severity: 'WARNING',
        sensorId: deviceId,
        houseId: houseId,
        message: deviceId + ' 제어 실패 (' + command + ') - ' + errorMsg,
        cooldownMinutes: 10,
        metadata: {
            deviceId: deviceId,
            command: command,
            error: errorMsg,
            houseId: houseId
        }
    },
    headers: { 'content-type': 'application/json' }
};

node.status({ fill: 'red', shape: 'dot', text: deviceId + ' 실패' });
return msg;

var pending = global.get('_pendingModbus');
node.warn('완료응답: pending=' + JSON.stringify(pending));

if (!pending || !pending.isLastWrite) return null;
// ★ requestId 가드 제거 — 자동화 발동(reqId=null)도 status 재발사

if (pending.requestId) {
    global.set('controlDone_' + pending.requestId, { done: true, timestamp: Date.now() });
    node.warn('Modbus 완료 저장됨: ' + pending.requestId);
}
global.set('_pendingModbus', null);

// ★ MUTEX 핵심 — write 완료 시점 갱신
global.set('_modbusLastWriteAt', Date.now());

setTimeout(function () {
    node.send({
        payload: { trigger: 'control_done' },
        _statusTrigger: true,
        _requestId: pending.requestId,  // null 도 OK — 자동화
    });
}, 300);

if (pending.requestId) {
    setTimeout(function () {
        global.set('controlDone_' + pending.requestId, null);
    }, 30000);
}

return null;

// Heartbeat 메시지 생성
// cpu_temp, disk_usage는 실배포 시 os 모듈로 교체

var farmId = env.get('FARM_ID') || global.get('FARM_ID') || 'default-farm';

// Node-RED 시작 시간 기록 (최초 실행 시)
var startTime = global.get('node_start_time');
if (!startTime) {
    startTime = Date.now();
    global.set('node_start_time', startTime);
}
var uptimeSec = Math.floor((Date.now() - startTime) / 1000);

var heartbeat = {
    farmId: farmId,
    timestamp: new Date().toISOString(),
    uptime: uptimeSec,
    cpu_temp: 0,
    disk_usage: 0,
    operating_state: flow.get('operating_state') || 'STOPPED',
    memory_usage: 0
};

msg.payload = JSON.stringify(heartbeat);
msg.topic = 'smartfarm/' + farmId + '/system/heartbeat';

node.status({ fill: 'green', shape: 'dot', text: 'uptime: ' + uptimeSec + 's' });

return msg;

// 수동 수집은 즉시 통과
if (msg.topic === 'manual') return msg;

const now = Date.now();
const nextCollectAt = global.get('nextCollectAt') || 0;

if (now < nextCollectAt) {
    const remain = Math.round((nextCollectAt - now) / 1000);
    node.status({ fill: 'blue', shape: 'ring', text: '대기 (' + remain + '초 후)' });
    return null; // 스킵
}

// houseConfig에서 최소 intervalSeconds 읽기
const config = global.get('houseConfig');
const houses = config && config.houses ? config.houses : [];
let interval = 600; // 기본 10분
for (const h of houses) {
    const hi = (h.collection && h.collection.intervalSeconds) || 600;
    if (hi < interval) interval = hi;
}
if (interval < 10) interval = 10; // 최소 10초 보장

global.set('nextCollectAt', now + interval * 1000);
global.set('appliedIntervalSeconds', interval);
node.status({ fill: 'green', shape: 'dot', text: '수집 (' + interval + '초 주기)' });
return msg;

const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
const FARM_ID = env.get('FARM_ID') || 'farm_0001';
const API_KEY = env.get('SENSOR_API_KEY') || 'smartfarm-sensor-key';

// operationMode가 아직 설정 안 된 경우 (재시작 직후)
// serverOnline도 체크하여 기본값 결정
const serverOnline = global.get('serverOnline');
const operationMode = global.get('operationMode') || (serverOnline === true ? 'online' : 'offline');

if (operationMode === 'online') {
    // 온라인: 서버에서 설정 가져오기
    // ⚠️ 템플릿 리터럴 금지! wrapper.sh 가 flows.json 을 텍스트로 sed 치환하므로
    //    코드나 주석 안의 FARM_ID 플레이스홀더(달러+중괄호)도 농장ID 로 덮어써진다.
    //    반드시 문자열 연결(+)로 작성할 것.
    msg.url = SERVER_URL + '/api/config/farm/' + FARM_ID;
    msg.method = 'GET';
    msg.headers = { 'Content-Type': 'application/json', 'x-api-key': API_KEY };
    node.status({ fill: 'blue', shape: 'dot', text: '온라인: 서버 config 요청' });
    return [msg, null, null]; // 출력1: HTTP Request
} else {
    // 오프라인: global 캐시 → SQLite 캐시
    const cachedConfig = global.get('houseConfig');
    if (cachedConfig) {
        msg.config = cachedConfig;
        node.status({ fill: 'yellow', shape: 'dot', text: '오프라인: global 캐시 사용' });
        return [null, msg, null]; // 출력2: 센서 수집으로
    } else {
        // SQLite config_cache에서 로드
        msg.topic = 'SELECT config_json FROM config_cache ORDER BY version DESC LIMIT 1';
        node.status({ fill: 'yellow', shape: 'ring', text: '오프라인: SQLite 캐시 조회' });
        return [null, null, msg]; // 출력3: SQLite 조회
    }
}

// 서버 응답 실패 → 캐시 폴백
if (msg.statusCode !== 200) {
    var cached = global.get('houseConfig');
    if (cached) {
        node.warn('⚠️ 서버 응답 실패 (status=' + msg.statusCode + '), 캐시 사용');
        msg.config = cached;
        return [msg, null, null];
    }
    node.error('❌ 서버 응답 실패, 캐시도 없음');
    return [null, null, null];
}

var response = msg.payload;
if (!response || !response.success) {
    node.error('설정 오류: ' + (response ? response.error || 'success=false' : 'payload null'));
    return [null, null, null];
}

var rawData = response.data;
var config;

// GET /api/config/farm/:farmId → data가 배열(하우스 목록)
if (Array.isArray(rawData)) {
    var FARM_ID = env.get('FARM_ID') || 'farm_0001';
    var enabledHouses = rawData.filter(function(h) { return h.enabled !== false; });
    var maxVersion = 0;
    rawData.forEach(function(h) {
        var v = h.configVersion || 0;
        if (v > maxVersion) maxVersion = v;
    });
    config = { farmId: FARM_ID, houses: enabledHouses, configVersion: maxVersion };
} else if (rawData && rawData.houses) {
    config = rawData;
} else {
    node.warn('⚠️ 예상 외 data 형식: ' + JSON.stringify(rawData).substring(0, 200));
    config = rawData;
}

if (!config || !config.houses) {
    node.error('❌ config 파싱 실패');
    var fb = global.get('houseConfig');
    if (fb) { msg.config = fb; return [msg, null, null]; }
    return [null, null, null];
}

// 항상 global 갱신 (최신 하우스 목록 반영)
global.set('houseConfig', config);
msg.config = config;

// configVersion 변경 감지 → ACK + SQLite 캐시 + 즉시 재수집
var cachedVersion = flow.get('lastConfigVersion') || 0;
if (config.configVersion > cachedVersion) {
    flow.set('lastConfigVersion', config.configVersion);
    node.warn('📋 설정 업데이트: v' + cachedVersion + ' → v' + config.configVersion + ' (' + config.houses.length + '개 하우스)');
    global.set('nextCollectAt', 0); // 즉시 재수집

    var cacheMsg = {
        topic: 'INSERT OR REPLACE INTO config_cache (id, farm_id, house_id, config_json, version, updated_at) VALUES (1, $1, $2, $3, $4, $5)',
        payload: [
            config.farmId || 'farm_0001',
            config.houses[0] ? config.houses[0].houseId : 'house_0001',
            JSON.stringify(config),
            config.configVersion || 1,
            new Date().toISOString()
        ]
    };

    var SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
    var API_KEY = env.get('SENSOR_API_KEY') || 'smartfarm-sensor-key';
    var ackMsg = {
        url: SERVER_URL + '/api/config/' + config.farmId + '/rpi-ack',
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': API_KEY },
        payload: {
            configVersion: config.configVersion,
            appliedAt: new Date().toISOString(),
            houses: config.houses.map(function(h) {
                return {
                    houseId: h.houseId,
                    intervalSeconds: (h.collection && h.collection.intervalSeconds) || 60
                };
            })
        }
    };
    node.warn('📤 RPi ACK 전송: v' + config.configVersion);
    return [msg, cacheMsg, ackMsg];
}

return [msg, null, null];

const rows = msg.payload || [];

if (rows.length > 0 && rows[0].config_json) {
    try {
        const config = JSON.parse(rows[0].config_json);
        global.set('houseConfig', config);
        msg.config = config;
        node.warn('📋 SQLite에서 config 복원 완료');
        node.status({ fill: 'green', shape: 'dot', text: 'SQLite config 복원' });
        return msg;
    } catch (e) {
        node.error('❌ config JSON 파싱 실패: ' + e.message);
    }
}

node.error('❌ SQLite config_cache도 비어있음 - 서버에 1회 접속 필요');
node.status({ fill: 'red', shape: 'dot', text: 'config 없음!' });
return null;

// ============================================================
// "③ 센서 데이터 수집" (fn_collect_sensors) — KS X 3267 센서 합류본 (2026-08-30 P3)
// 위치: "센서 수집" 탭 → "③ 센서 데이터 수집". 코드 전체 교체 (출력·배선 변경 없음)
// 변경: modbusReadings 에 global.ks3267Readings(3분 TTL) 를 합류 — 표준 센서가 기존 파이프라인
//       (SQLite 오프라인 저장·서버 전송·자동화 평가)을 그대로 탄다.
// ============================================================
// ③ 센서 데이터 수집 — 시뮬레이션 격리 버전 (2026-08-29, B4)
// "센서 수집" 탭 → "③ 센서 데이터 수집" 함수 노드 코드 전체 교체
//
// 바뀐 것:
//   · Modbus 값이 없을 때 **값을 지어내지 않는다.** 그 센서는 이번 사이클에서 빠지고, 서버의
//     SensorDataStalled 가 울린다. (farm_0006 이 5월부터 USB-485 없이 시뮬레이션 값을 실측처럼
//     13만 행 저장한 사고의 근본 조치)
//   · 시뮬레이션은 SIM_MODE=1 일 때만 (ecosystem 이 /home/lhk/smartfarm/.sim-mode 파일이 있으면 주입).
//     그때도 payload.quality = 'simulated' 를 붙여 서버가 지표·알림에서 제외한다.
//   · 버스 장애 감지(2사이클 연속)는 그대로.

const config = msg.config || global.get('houseConfig');
const modbusRaw = msg.payload;
const SIM_MODE = String(env.get('SIM_MODE') || '') === '1';

if (!config) {
    node.error('❌ config 없음, 수집 중단');
    return null;
}

// Modbus 실측 데이터 파싱
let realData = {};
if (Array.isArray(modbusRaw) && modbusRaw.length >= 2) {
    realData.humidity = modbusRaw[0] / 10;
    let temp = modbusRaw[1] / 10;
    if (modbusRaw[1] > 0x7FFF) {
        temp = -(0xFFFF - modbusRaw[1] + 1) / 10;
    }
    realData.temperature = temp;
    node.warn('🌡️ Modbus 실측: ' + realData.temperature + '°C, ' + realData.humidity + '%RH');
} else if (SIM_MODE) {
    node.warn('⚠️ Modbus 데이터 없음 — SIM_MODE=1: 시뮬레이션 값 사용 (quality=simulated)');
} else {
    node.warn('⚠️ Modbus 데이터 없음 — 시뮬레이션 금지, 실측 없는 센서는 이번 사이클 생략');
}

// msg.modbusReadings가 있으면 사용 (sensor-modbus-read-flow 경유)
// KS X 3267 표준 센서 노드 값 합류 (P3, 2026-08-30) — ks3267d 데몬 → fn_ks_status 가 3분 이내에 넣은 값만.
// 낡은 값(데몬 중단)은 버린다 — 값을 지어내지 않는 원칙과 같은 맥락.
var ksR = global.get('ks3267Readings');
var ksVals = (ksR && ksR.values && (Date.now() - (ksR.t || 0)) < 180000) ? ksR.values : {};
var modbusReadings = Object.assign({}, ksVals, msg.modbusReadings || realData || {});

let housesToCollect = [];
if (config.houses && config.houses.length > 0) {
    housesToCollect = config.houses.filter(h => h.enabled !== false);
} else if (config.sensors) {
    housesToCollect = [{ houseId: config.houseId, sensors: config.sensors }];
}
if (housesToCollect.length === 0) {
    node.error('❌ 활성 하우스 없음');
    return null;
}

const farmId = config.farmId;
const deviceId = 'rpi_' + (global.get('farmId') || env.get('FARM_ID') || 'farm_0001').replace('farm_', '');
const messages = [];
let simulatedCount = 0;
let skippedCount = 0;

// 실측이 없을 때 값을 만드는 곳은 여기뿐 — SIM_MODE 에서만 호출된다
function simulate(sensor) {
    switch (sensor.sensorId) {
        case 'temp_0001':     return parseFloat((Math.random() * 10 + 20).toFixed(1));
        case 'humidity_0001': return parseFloat((Math.random() * 20 + 50).toFixed(1));
        case 'co2_0001':      return parseInt(Math.random() * 200 + 400);
        default:
            if (sensor.type === 'number') {
                const min = sensor.min !== null ? sensor.min : 0;
                const max = sensor.max !== null ? sensor.max : 100;
                return parseFloat((Math.random() * (max - min) + min).toFixed(sensor.precision || 1));
            }
            if (sensor.type === 'boolean') return Math.random() > 0.5;
            return 'OK';
    }
}

for (const house of housesToCollect) {
    const sensors = house.sensors || [];
    const houseId = house.houseId;
    const enabledSensors = sensors.filter(s => s.enabled);
    if (enabledSensors.length === 0) continue;

    const sensorData = {};
    let houseSimulated = false;
    for (const sensor of enabledSensors) {
        try {
            let value;
            if (modbusReadings[sensor.sensorId] !== undefined) {
                value = modbusReadings[sensor.sensorId];                       // 1) 모듈별 읽기
            } else if (sensor.sensorId === 'temp_0001' && realData.temperature !== undefined) {
                value = realData.temperature;                                  // 2) 기본 온습도 모듈
            } else if (sensor.sensorId === 'humidity_0001' && realData.humidity !== undefined) {
                value = realData.humidity;
            } else if (SIM_MODE) {
                value = simulate(sensor);                                      // 3) 시뮬레이션 (명시적으로 켰을 때만)
                houseSimulated = true;
                simulatedCount++;
            } else {
                skippedCount++;                                                // 4) 실측 없음 → 생략 (지어내지 않음)
                continue;
            }
            sensorData[sensor.sensorId] = value;
        } catch (e) {
            node.error('센서 읽기 실패: ' + sensor.sensorId + ' - ' + e.message);
        }
    }
    if (Object.keys(sensorData).length === 0) continue;

    messages.push({
        payload: {
            farmId: farmId,
            houseId: houseId,
            data: sensorData,
            timestamp: new Date().toISOString(),
            quality: houseSimulated ? 'simulated' : 'measured',
            deviceInfo: {
                deviceId: deviceId,
                ip: global.get('systemIp') || null,
                version: '2.1.0-offline'
            }
        }
    });
}

const totalSensors = messages.reduce((sum, m) => sum + Object.keys(m.payload.data).length, 0);
if (messages.length === 0) {
    node.warn('⚠️ 전송할 실측 없음 (생략 ' + skippedCount + '개) — 서버 SensorDataStalled 로 감지된다');
    node.status({ fill: 'red', shape: 'ring', text: '실측 없음 (' + skippedCount + ' 생략)' });
} else {
    node.warn('📡 ' + messages.length + '개 하우스, 총 ' + totalSensors + '개 센서 수집' +
        (simulatedCount ? ' (시뮬레이션 ' + simulatedCount + ')' : '') + (skippedCount ? ' (생략 ' + skippedCount + ')' : ''));
    node.status({ fill: simulatedCount ? 'yellow' : 'green', shape: 'dot',
        text: messages.length + '개 하우스 ' + totalSensors + '개 센서' + (simulatedCount ? ' SIM' : '') });
}

// ━━━ Modbus 버스 전체 장애 감지 (기존 그대로) ━━━
var busAlarmMsg = null;
var totalModbusSensors = 0;
var totalModbusFailed = 0;
for (const house of housesToCollect) {
    const sensors = (house.sensors || []).filter(s => s.enabled);
    for (const sensor of sensors) {
        if (sensor.modbus && sensor.modbus.unitId != null) {
            totalModbusSensors++;
            if (modbusReadings[sensor.sensorId] === undefined) totalModbusFailed++;
        }
    }
}
if (totalModbusSensors >= 2 && totalModbusFailed === totalModbusSensors) {
    var busFailCount = (flow.get('busFailCount') || 0) + 1;
    flow.set('busFailCount', busFailCount);
    node.warn('🔌 Modbus 버스 전체 실패 (' + busFailCount + '사이클 연속)');
    if (busFailCount >= 2) {
        var lastBusAlarm = flow.get('lastBusAlarmTime') || 0;
        var now = Date.now();
        if (now - lastBusAlarm > 60 * 60 * 1000) {
            flow.set('lastBusAlarmTime', now);
            busAlarmMsg = {
                payload: {
                    alarm_type: 'MODBUS_BUS_FAILURE',
                    severity: 'CRITICAL',
                    message: 'Modbus RS-485 버스 전체 통신 장애 — ' + totalModbusSensors + '개 센서 모두 응답 없음 (' + busFailCount + '사이클 연속)',
                    cooldownMinutes: 60,
                    metadata: { totalModbusSensors: totalModbusSensors, consecutiveFailCycles: busFailCount }
                },
                headers: { 'content-type': 'application/json' }
            };
            node.warn('🚨 Modbus 버스 장애 알림 전송!');
        }
    }
} else {
    if (flow.get('busFailCount') > 0) node.warn('✅ Modbus 버스 정상 복구');
    flow.set('busFailCount', 0);
}

return [messages.length ? messages : null, busAlarmMsg];

const { farmId, houseId, data, timestamp } = msg.payload;
const ts = timestamp || new Date().toISOString();

// 센서 데이터 수집
const entries = Object.entries(data).filter(([k, v]) => v !== null && v !== undefined);

if (entries.length === 0) {
    node.warn('⚠️ 저장할 데이터 없음');
    return null;
}

// 위치 파라미터 쿼리로 개별 INSERT (센서별 msg 배열)
// node-red-node-sqlite msg.topic 모드: msg.payload 배열 + $N 파라미터 사용
const messages = entries.map(([sensorId, value]) => ({
    topic: 'INSERT INTO sensor_data (timestamp, farm_id, house_id, sensor_id, value, synced) VALUES ($1, $2, $3, $4, $5, 0)',
    payload: [ts, farmId, houseId, sensorId, value],
    _insertTimestamp: ts,
    _sensorCount: entries.length,
    _isLast: false,
    _originalPayload: msg.payload,
    _houseId: houseId
}));

// 마지막 메시지에 표시 (모드 분기용)
const srvOnline = global.get('serverOnline');
const opMode = global.get('operationMode') || (srvOnline === true ? 'online' : 'offline');
messages[messages.length - 1]._isLast = true;
messages[messages.length - 1]._operationMode = opMode;

node.warn('💾 SQLite INSERT: ' + houseId + ' ' + entries.length + '건');
return [messages];

// 마지막 INSERT 메시지만 처리 (나머지는 통과)
if (!msg._isLast) { return null; }

const serverOnline = global.get('serverOnline');
const mode = msg._operationMode || global.get('operationMode') || (serverOnline === true ? 'online' : 'offline');

// 자동화 평가용 메시지 (모드와 무관하게 항상 실행)
var evalMsg = null;
if (msg._originalPayload) {
    evalMsg = {
        sensorData: {
            farmId: msg._originalPayload.farmId,
            houseId: msg._originalPayload.houseId,
            data: msg._originalPayload.data
        }
    };
}

// === 디버그 로그 추가 ===
if (evalMsg) {
    node.warn('📊 자동화 평가 전달: ' + evalMsg.sensorData.farmId + '/' + evalMsg.sensorData.houseId);
} else {
    node.warn('⚠️ evalMsg null: _originalPayload 없음');
}

// 원본 payload 복원 (서버 전송용)
if (msg._originalPayload) { msg.payload = msg._originalPayload; }

if (mode === 'online') {
    const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
    const API_KEY = env.get('SENSOR_API_KEY') || 'smartfarm-sensor-key';

    msg.url = SERVER_URL + '/api/sensors/collect';
    msg.method = 'POST';
    msg.headers = { 'Content-Type': 'application/json', 'x-api-key': API_KEY };
    msg.requestTimeout = 10000;

    node.status({ fill: 'green', shape: 'dot', text: '온라인: SQLite ✓ + 서버 전송' });
    return [msg, null, evalMsg];
} else {
    node.warn('📴 오프라인: SQLite만 저장 (synced=0)');
    node.status({ fill: 'yellow', shape: 'dot', text: '오프라인: SQLite ✓ (' + msg._sensorCount + '건)' });
    msg.payload = '오프라인 저장 완료: ' + msg._sensorCount + '건';
    return [null, msg, evalMsg];
}

if (msg.statusCode === 201 || msg.statusCode === 200) {
    node.warn('✅ 서버 전송 성공 → synced=1');

    const syncMsg = {
        topic: 'UPDATE sensor_data SET synced = 1 WHERE timestamp = $1 AND house_id = $2 AND synced = 0',
        payload: [msg._insertTimestamp, msg._houseId]
    };

    node.status({ fill: 'green', shape: 'dot', text: '서버 전송 ✓ + synced' });
    return [syncMsg, msg];
} else {
    node.warn('⚠️ 서버 전송 실패 (' + msg.statusCode + '): synced=0 유지');
    node.status({ fill: 'yellow', shape: 'ring', text: '전송 실패 (synced=0)' });
    return [null, msg];
}

var errMsg = msg.error ? msg.error.message : 'unknown';
node.warn('❌ SQLite 쓰기 에러: ' + errMsg);
node.status({fill:'red',shape:'dot',text:'SQLite 에러: ' + errMsg.substring(0,30)});

// 에러 카운트 (모니터링용)
var count = global.get('sqliteErrorCount') || 0;
global.set('sqliteErrorCount', count + 1);
global.set('lastSqliteError', {message: errMsg, timestamp: new Date().toISOString()});

return null;

// ================================================================
// Modbus 센서 읽기 준비 — 자동 매핑 추가 버전 (2026-05-01)
// ================================================================
// "센서 수집" 탭 → "Modbus 센서 읽기 준비" 함수 노드 코드 전체 교체
//
// 변경: sensor.modbus 가 비어있을 때 global.sensorModules 의 매칭 모듈로 자동 채움
//   - sensorId prefix 로 register index 추론 (temp_* → 0, humidity_* → 1)
//   - 모듈 등록만 하면 모든 house 의 sensor 가 자동 동작 (UI 매핑 불필요)
// ================================================================

const config = msg.config || global.get('houseConfig');
if (!config) { return [null, msg]; }

// ───────── 자동 매핑: sensor.modbus 비어있으면 global.sensorModules 로 채움 ─────────
const sensorModules = global.get('sensorModules') || [];
const moduleByType = {};
for (const mod of sensorModules) {
    if (mod && mod.sensorType) moduleByType[mod.sensorType] = mod;
}

function inferType(sensorId) {
    const id = String(sensorId || '').toLowerCase();
    // XY-MD02 (humidity 먼저 변종): register 0 = 습도, register 1 = 온도
    if (id.startsWith('temp')) return { type: 'temperature_humidity', registerIndex: 1 };
    if (id.startsWith('humid')) return { type: 'temperature_humidity', registerIndex: 0 };
    if (id.startsWith('co2')) return { type: 'co2', registerIndex: 0 };
    if (id.startsWith('soil_temp')) return { type: 'soil', registerIndex: 0 };
    if (id.startsWith('soil_moist')) return { type: 'soil', registerIndex: 1 };
    if (id.startsWith('ec')) return { type: 'ec', registerIndex: 0 };
    if (id.startsWith('ph')) return { type: 'ph', registerIndex: 0 };
    return null;
}

let autoMapped = 0;
let stalefixed = 0;
for (const house of (config.houses || [])) {
    for (const sensor of (house.sensors || [])) {
        const inferred = inferType(sensor.sensorId);
        if (!inferred) continue;
        const mod = moduleByType[inferred.type];
        if (!mod) continue;
        const m = sensor.modbus;
        // 등록된 모듈과 매핑이 일치하면 그대로 사용
        const matches = m && m.unitId === mod.unitId
            && m.address === (mod.address || 0)
            && m.fc === (mod.fc || 3)
            && m.quantity === (mod.quantity || 1);
        if (matches) continue;
        // 비어있거나 stale 매핑 → 자동매핑으로 덮어쓰기
        const wasStale = m && m.unitId != null;
        sensor.modbus = {
            unitId: mod.unitId,
            fc: mod.fc || 3,
            address: mod.address || 0,
            quantity: mod.quantity || 1,
            registerIndex: inferred.registerIndex,
            divider: mod.divider || 1,
            signed: mod.signed || false,
        };
        if (wasStale) stalefixed++; else autoMapped++;
    }
}

// ───────── 모든 sensor 모음 ─────────
const houses = config.houses || (config.sensors ? [config] : []);
const allSensors = [];

for (const house of houses) {
    if (house.enabled === false) continue;
    const sensors = (house.sensors || []).filter(s => s.enabled !== false && s.modbus && s.modbus.unitId != null && s.modbus.address != null);
    for (const sensor of sensors) {
        allSensors.push({
            houseId: house.houseId || house.id,
            sensorId: sensor.sensorId,
            unitId: sensor.modbus.unitId,
            fc: sensor.modbus.fc || 3,
            address: sensor.modbus.address,
            quantity: sensor.modbus.quantity || 1,
            registerIndex: sensor.modbus.registerIndex || 0,
            divider: sensor.modbus.divider || 1,
            signed: sensor.modbus.signed || false
        });
