    const key = s.unitId + ':' + s.fc + ':' + s.address + ':' + s.quantity;
    if (!sensorMap[key]) {
        sensorMap[key] = [];
        uniqueReads.push({
            key: key,
            unitId: s.unitId,
            fc: s.fc,
            address: s.address,
            quantity: s.quantity
        });
    }
    sensorMap[key].push(s);
}

