    var sensors, collection, devices, crops;
    try { sensors = JSON.parse(row.sensors || '[]'); } catch(e) { sensors = []; }
    try { collection = JSON.parse(row.collection || '{}'); } catch(e) { collection = {}; }
    try { devices = JSON.parse(row.devices || '[]'); } catch(e) { devices = []; }
    try { crops = JSON.parse(row.crops || '[]'); } catch(e) { crops = []; }
    return {
        _id: row.id,
        farmId: row.farm_id,
        houseId: row.house_id,
        houseName: row.house_name,
        sensors: sensors,
        collection: collection,
        devices: devices,
        crops: crops,
        cropType: row.crop_type || '',
        cropVariety: row.crop_variety || '',
        plantingDate: row.planting_date || '',
        deviceCount: row.device_count || 0,
        enabled: row.enabled === 1,
        configVersion: row.config_version || 1,
        createdAt: row.created_at,
        updatedAt: row.updated_at
    };
}

if (msg._mode === 'single') {
    if (rows.length === 0) {
        var cachedConfig = global.get('houseConfig');
        if (cachedConfig) {
            msg.payload = { success: true, data: cachedConfig, source: 'cache' };
        } else {
            msg.payload = { success: false, error: 'House not found' };
            msg.statusCode = 404;
        }
    } else {
        msg.payload = { success: true, data: formatRow(rows[0]) };
    }
} else {
    var configData = {
        farmId: msg._farmId,
        farmName: '스마트팜',
        houses: rows.map(function(h) {
            var formatted = formatRow(h);
            return {
                houseId: formatted.houseId,
                name: formatted.houseName,
                houseName: formatted.houseName,
                sensors: formatted.sensors,
                collection: formatted.collection,
                enabled: formatted.enabled,
                devices: formatted.devices,
                deviceCount: formatted.devices.length || formatted.deviceCount || 0
            };
        })
    };
    msg.payload = { success: true, data: configData };
}
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

var farmId = msg._farmId || 'farm_0001';
msg.topic = 'SELECT * FROM house_configs WHERE farm_id = $1 ORDER BY created_at ASC';
msg.payload = [farmId];
msg._syncFarmId = farmId;
return msg;

var rows = msg.payload || [];
var houses = rows.map(function(row) {
    var sensors, collection, devices;
    try { sensors = JSON.parse(row.sensors || '[]'); } catch(e) { sensors = []; }
    try { collection = JSON.parse(row.collection || '{}'); } catch(e) { collection = {}; }
    try { devices = JSON.parse(row.devices || '[]'); } catch(e) { devices = []; }
    return {
