    houses: houses
};
global.set('houseConfig', config);
node.warn('🔄 houseConfig 동기화 완료: ' + houses.length + '개 하우스');
return null;

// node-red-node-sqlite는 단일 PRAGMA만 실행 가능
// 순차 체인으로 PRAGMA 실행
// ⚠️ auto_vacuum 은 반드시 첫 줄 — 빈 DB 에 테이블 생성 전 설정해야
//    파일 헤더에 기록됨. 기존 DB 에서는 무시되므로 안전.
var pragmas = [
  'PRAGMA auto_vacuum = INCREMENTAL',
  'PRAGMA journal_mode = WAL',
  'PRAGMA busy_timeout = 5000',
  'PRAGMA synchronous = NORMAL',
  'PRAGMA cache_size = -8000',
  'PRAGMA temp_store = MEMORY'
];
msg._pragmaList = pragmas;
msg._pragmaIdx = 0;
msg.topic = pragmas[0];
node.warn('⚙️ SQLite PRAGMA 설정 시작 (' + pragmas.length + '개)');
return msg;

var idx = (msg._pragmaIdx || 0) + 1;
var list = msg._pragmaList || [];
if (idx < list.length) {
  msg._pragmaIdx = idx;
  msg.topic = list[idx];
  return [msg, null];
}
node.warn('✅ PRAGMA ' + list.length + '개 설정 완료');
return [null, msg];

msg.topic = `
