}

const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
const API_KEY = env.get('SENSOR_API_KEY') || '';

function pad4(id) {
    if (!id) return id;
    return id.replace(/_(\d{1,3})$/, function (m, n) { return '_' + n.padStart(4, '0'); });
}

const byHouse = {};
for (const row of rows) {
    const fid = pad4(row.farm_id);
    const hid = pad4(row.house_id);
    const houseKey = fid + '_' + hid;
    if (!byHouse[houseKey]) {
        byHouse[houseKey] = { farmId: fid, houseId: hid, rows: [] };
    }
    byHouse[houseKey].rows.push(row);
}

const queue = [];
for (const house of Object.values(byHouse)) {
    const grouped = {};
    for (const row of house.rows) {
        if (!grouped[row.timestamp]) {
            grouped[row.timestamp] = {
                timestamp: row.timestamp,
                data: {},
//                deviceInfo: { deviceId: 'rpi_0001', ip: '192.168.137.30', version: '1.0.0' }
//                deviceInfo: { deviceId: 'rpi_0001', ip: global.get('systemIp') || null, version: '1.0.0' }
                deviceInfo: { deviceId: 'rpi_' + (global.get('farmId') || env.get('FARM_ID') || 'farm_0001').replace('farm_', ''), ip: global.get('systemIp') || null, version: '1.0.0' }


            };
        }
        grouped[row.timestamp].data[pad4(row.sensor_id)] = row.value;
    }
    queue.push({
        url: SERVER_URL + '/api/sensors/batch',
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': API_KEY },
        payload: {
            farmId: house.farmId,
            houseId: house.houseId,
            dataArray: Object.values(grouped)
        },
        _syncIds: house.rows.map(r => r.id),
        _syncCount: house.rows.length
    });
}

var initial = flow.get('syncInitialCount') || 0;
if (initial === 0) {
    var totalUnsynced = global.get('totalUnsynced') || 0;
    flow.set('syncInitialCount', totalUnsynced > 0 ? totalUnsynced : rows.length);
}

global.set('syncQueueTotal', queue.length);
global.set('syncQueue', queue);
var houseCount = queue.length;
var soFar = flow.get('syncedSoFar') || 0;
node.warn('📤 동기화 큐 생성: ' + rows.length + '건 (' + houseCount + '개 하우스) 누적: ' + soFar);
node.status({ fill: 'blue', shape: 'dot', text: '전송 중: 1/' + houseCount });

var first = queue.shift();
global.set('syncQueue', queue);

flow.set('currentSyncIds', first._syncIds);
flow.set('currentSyncCount', first._syncCount);

return first;

if (msg.statusCode === 201 || msg.statusCode === 200) {
    var ids = msg._syncIds || flow.get('currentSyncIds') || [];
    var syncCount = msg._syncCount || flow.get('currentSyncCount') || ids.length || 0;

    if (ids.length > 0) {
        var safeIds = ids.filter(function (id) { return Number.isInteger(id) && id > 0; });
        if (safeIds.length === 0) { return [null, null]; }
        var placeholders = safeIds.map(function (_, i) { return '$' + (i + 1); }).join(',');
        msg.topic = 'UPDATE sensor_data SET synced = 1 WHERE id IN (' + placeholders + ')';
        msg.payload = safeIds;

        var soFar = (flow.get('syncedSoFar') || 0) + syncCount;
        flow.set('syncedSoFar', soFar);

        global.set('lastSyncResult', { time: new Date().toISOString(), success: true, count: syncCount });
        node.warn('✅ 동기화 성공: ' + syncCount + '건 (누적: ' + soFar + ')');
        node.status({ fill: 'green', shape: 'dot', text: '누적: ' + soFar + '건' });
        return [msg, null];
    }
} else {
    flow.set('syncRunning', false);
    global.set('lastSyncResult', { time: new Date().toISOString(), success: false, count: 0, error: msg.statusCode });
    node.warn('⚠️ 동기화 실패 (' + msg.statusCode + '): 다음 주기에 재시도');
    node.status({ fill: 'red', shape: 'ring', text: '실패: ' + msg.statusCode });
}

return [null, null];

if (flow.get('syncPaused')) {
    flow.set('syncRunning', false);
    node.status({ fill: 'yellow', shape: 'ring', text: '동기화 중지됨' });
    return null;
}

var queue = global.get('syncQueue') || [];
if (queue.length > 0) {
    var next = queue.shift();
    global.set('syncQueue', queue);
    var total = (global.get('syncQueueTotal') || 0);
    node.status({ fill: 'blue', shape: 'dot', text: '전송 중: ' + (total - queue.length) + '/' + total });

    flow.set('currentSyncIds', next._syncIds);
    flow.set('currentSyncCount', next._syncCount);

    setTimeout(function () { node.send([next, null]); }, 200);
    return null;
} else {
    node.status({ fill: 'green', shape: 'dot', text: '큐 완료, 다음 배치 확인' });
    setTimeout(function () { node.send([null, { payload: 'next_batch' }]); }, 500);
    return null;
}

const mode = global.get('operationMode') || 'online';

if (mode !== 'online') {
    node.status({ fill: 'yellow', shape: 'ring', text: '오프라인 - 규칙 동기화 대기' });
    return null;
}

msg.topic = 'SELECT * FROM automation_rules WHERE synced = 0';
return msg;

const rows = msg.payload || [];

if (rows.length === 0) {
    node.status({ fill: 'green', shape: 'dot', text: '규칙 동기화 완료 (0건)' });
