        syncPaused: flow.get('syncPaused') || false,
        syncRunning: flow.get('syncRunning') || false,
        syncInitialCount: flow.get('syncInitialCount') || 0,
        syncedSoFar: flow.get('syncedSoFar') || 0,
        lastSyncResult: global.get('lastSyncResult') || null
    }
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

flow.set('syncPaused', false);
flow.set('syncRunning', true);
flow.set('syncedSoFar', 0);

// totalUnsynced에서 초기값 설정 (상태 API 폴링 시 저장됨)
