var farmId = env.get('FARM_ID') || 'farm_0001';
var houseId = env.get('HOUSE_ID') || 'house_0001';
var serverUrl = env.get('SERVER_URL') || 'https://api.smartgreen.kr';

msg.url = serverUrl + '/api/automation/' + farmId + '/active?houseId=' + houseId;
msg.method = 'GET';
// msg.headers = { 'x-api-key': 'smartfarm-sensor-key' };
msg.headers = { 'x-api-key': env.get('SENSOR_API_KEY') || global.get('sensorApiKey') || '' };
return msg;

var data = msg.payload;
if (!data || !data.success) {
    node.status({ fill: 'red', shape: 'dot', text: '서버 응답 실패' });
    return null;
}

// 견고성: backend 가 단일 진실 원천 — MQTT 발송 실패해도 5분마다 fetch 로 sync 보장
// (이전 정책: MQTT 권한 소스 → MQTT 끊기면 RPi 영구 미동기화 결함)
//
// 다중 하우스: autoDevices 는 'houseId:deviceId' 복합키 배열로 관리한다.
//   신규 응답: data.houses = { house_0001: {active, autoDevices:[deviceId..]}, ... }
//   옛  응답: data.active + data.autoDevices (평면) — 하위 호환 처리
var dkey = global.get('dkey') || function (h, dv) { return (h || 'house_0001') + ':' + dv; };
var currentAutoDevices = global.get('autoDevices') || [];

function toComposite(list, hId) {
    return (list || []).map(function (x) {
        var v = String(x);
        return v.indexOf(':') > -1 ? v : dkey(hId, v);
    });
}

var newAutoDevices = [];
var activeHouses = [];

if (data.houses && typeof data.houses === 'object') {
    Object.keys(data.houses).forEach(function (hid) {
        if (hid === 'all') return;               // 백엔드 옛 기본키 방어
        var h = data.houses[hid] || {};
        if (!h.active) return;
        activeHouses.push(hid);
        newAutoDevices = newAutoDevices.concat(toComposite(h.autoDevices, hid));
    });
} else if (data.active) {
    newAutoDevices = toComposite(data.autoDevices, 'house_0001');
    activeHouses.push('house_0001');
}

var changed = JSON.stringify(currentAutoDevices) !== JSON.stringify(newAutoDevices);
if (changed) {
    global.set('autoDevices', newAutoDevices);
    node.warn('🔄 서버에서 autoDevices 동기화: ' + JSON.stringify(currentAutoDevices) + ' → ' + JSON.stringify(newAutoDevices));
}

node.status({
    fill: newAutoDevices.length > 0 ? 'green' : 'yellow',
    shape: 'dot',
    text: newAutoDevices.length > 0
        ? '자동화 적용중 (' + activeHouses.length + '하우스 ' + newAutoDevices.length + '장치)'
        : '자동화 미적용'
});

node.warn('🔄 서버 동기화: 활성하우스=' + JSON.stringify(activeHouses) + ', 장치=' + JSON.stringify(newAutoDevices));
return null;

// 오프라인이거나 사용자가 시작하지 않았으면 흐르지 않는다.
// 센서 동기화와 같은 규칙 — 자동으로 켜지지 않게 한다.
const mode = global.get('operationMode') || 'online';
if (mode !== 'online') {
    node.status({ fill: 'yellow', shape: 'ring', text: '오프라인 - 대기' });
    return null;
}

const paused = flow.get('ctrlSyncPaused');
if (paused === undefined || paused === null || paused === true) {
    node.status({ fill: 'grey', shape: 'ring', text: '대기 (수동 시작 필요)' });
    return null;
}

// 한 번에 200건 — 서버 배치 상한(500)보다 낮게 잡아 여유를 둔다.
// 다 보내면 '다음 배치' 가 이 노드로 되돌려 나머지를 이어서 처리한다.
msg.topic = `SELECT id, timestamp, device_id, command, source
FROM control_logs
WHERE synced IS NULL OR synced = 0
ORDER BY timestamp ASC
LIMIT 200`;

node.status({ fill: 'blue', shape: 'ring', text: '미동기화 조회 중...' });
return msg;

const rows = msg.payload || [];

if (rows.length === 0) {
    flow.set('ctrlSyncRunning', false);
    node.status({ fill: 'green', shape: 'dot', text: '동기화 완료 (남은 건 없음)' });
    return null;
}

const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
const API_KEY = env.get('SENSOR_API_KEY') || '';
const FARM_ID = env.get('FARM_ID') || 'farm_0001';

// 로컬 테이블에는 house_id 컬럼이 없다 (다중하우스 전환 이전 기록).
// 같은 기간 서버 기록이 100% house_0001 이고 제어 장치가 있는 하우스도 그곳뿐이라
// 서버가 house_0001 로 채운다. 여기서는 굳이 보내지 않는다.
msg.url = SERVER_URL + '/internal/control-log/batch';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json', 'x-api-key': API_KEY };
msg.payload = {
    farmId: FARM_ID,
    logs: rows.map(function (r) {
        return {
            localId: r.id,
            timestamp: r.timestamp,
            deviceId: r.device_id,
            command: r.command,
            source: r.source
        };
    })
};

msg._ctrlIds = rows.map(function (r) { return r.id; });
msg._ctrlCount = rows.length;

node.status({ fill: 'blue', shape: 'dot', text: '전송 중: ' + rows.length + '건' });
return msg;

// 서버는 멱등이라 이미 있는 건 skipped 로 돌려준다.
// 삽입이든 중복이든 '서버가 확인함' 이므로 로컬은 synced=1 로 마킹한다.
if (msg.statusCode === 200 || msg.statusCode === 201) {
    const body = msg.payload || {};
    const ids = msg._ctrlIds || [];
    const count = msg._ctrlCount || ids.length || 0;

    if (ids.length === 0) { return [null, null]; }

    const safeIds = ids.filter(function (id) { return Number.isInteger(id) && id > 0; });
    if (safeIds.length === 0) { return [null, null]; }

    const placeholders = safeIds.map(function (_, i) { return '$' + (i + 1); }).join(',');
    msg.topic = 'UPDATE control_logs SET synced = 1 WHERE id IN (' + placeholders + ')';
    msg.payload = safeIds;

    const soFar = (flow.get('ctrlSyncedSoFar') || 0) + count;
    flow.set('ctrlSyncedSoFar', soFar);

    const ins = body.inserted || 0;
    const skp = body.skipped || 0;
    global.set('lastCtrlSyncResult', {
        time: new Date().toISOString(), success: true,
        count: count, inserted: ins, skipped: skp
    });

    node.warn('✅ 제어이력 동기화: ' + count + '건 (신규 ' + ins + ' / 중복 ' + skp + ', 누적 ' + soFar + ')');
    node.status({ fill: 'green', shape: 'dot', text: '누적: ' + soFar + '건' });
    return [msg, null];
}

// 실패 — 로컬을 마킹하지 않으므로 다음 주기에 그대로 재시도된다
flow.set('ctrlSyncRunning', false);
global.set('lastCtrlSyncResult', {
    time: new Date().toISOString(), success: false, count: 0, error: msg.statusCode
});
node.warn('⚠️ 제어이력 동기화 실패 (' + msg.statusCode + '): 다음 주기에 재시도');
node.status({ fill: 'red', shape: 'ring', text: '실패: ' + msg.statusCode });
return [null, null];

// 아직 남았을 수 있으니 조회 노드로 되돌린다.
// 남은 게 없으면 '배치 준비' 가 null 을 반환하며 루프가 끝난다.
if (flow.get('ctrlSyncPaused')) {
    flow.set('ctrlSyncRunning', false);
    node.status({ fill: 'yellow', shape: 'ring', text: '중지됨' });
    return null;
}

// 서버·SD카드에 여유를 주려고 약간 텀을 둔다
setTimeout(function () { node.send({ payload: 'next' }); }, 500);
return null;

const row = (msg.payload || [])[0] || {};
const unsynced = row.unsynced || 0;

// 시작 버튼이 초기 건수를 잡을 때 쓴다
global.set('ctrlTotalUnsynced', unsynced);

msg.payload = {
    success: true,
    data: {
        kind: 'control',
        total: row.total || 0,
        synced: row.synced || 0,
        unsynced: unsynced,
        oldestUnsynced: row.oldest_unsynced || null,
        operationMode: global.get('operationMode') || 'unknown',
        syncPaused: flow.get('ctrlSyncPaused') !== false,
        syncRunning: flow.get('ctrlSyncRunning') || false,
        syncInitialCount: flow.get('ctrlSyncInitialCount') || 0,
        syncedSoFar: flow.get('ctrlSyncedSoFar') || 0,
        lastSyncResult: global.get('lastCtrlSyncResult') || null
    }
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

flow.set('ctrlSyncPaused', false);
flow.set('ctrlSyncRunning', true);
flow.set('ctrlSyncedSoFar', 0);

const total = global.get('ctrlTotalUnsynced') || 0;
flow.set('ctrlSyncInitialCount', total);

node.warn('▶️ 제어이력 동기화 시작 (미동기화: ' + total + '건)');

msg.payload = { success: true, message: '제어 이력 동기화를 시작합니다 (' + total + '건)' };
msg.headers = { 'Access-Control-Allow-Origin': '*' };

// 응답은 즉시, 전송 루프는 두 번째 출력으로 바로 착수
node.send([null, { payload: 'start' }]);
return [msg, null];

flow.set('ctrlSyncPaused', true);
flow.set('ctrlSyncRunning', false);
node.warn('⏸️ 제어이력 동기화 중지');
msg.payload = { success: true, message: '제어 이력 동기화를 중지했습니다' };
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

// 서버로 보내지 않고 '처리됨' 으로만 표시한다.
// 되돌릴 수 없으므로 화면에서 확인을 받은 뒤 호출된다.
flow.set('ctrlSyncPaused', true);
flow.set('ctrlSyncRunning', false);
msg.topic = 'UPDATE control_logs SET synced = 1 WHERE synced IS NULL OR synced = 0';
return msg;

node.warn('⏭️ 제어 이력 미동기화분을 동기화 안함으로 처리');
msg.payload = { success: true, message: '제어 이력 미동기화분을 동기화 안함으로 처리했습니다' };
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

// 로컬을 마킹하지 않았으므로 데이터는 그대로 남는다 — 다음 주기에 재시도된다
flow.set('ctrlSyncRunning', false);
global.set('lastCtrlSyncResult', {
    time: new Date().toISOString(),
    success: false,
    count: 0,
    error: (msg.error && msg.error.message) || 'unknown'
});
node.warn('❌ 제어이력 동기화 오류: ' + ((msg.error && msg.error.message) || 'unknown'));
node.status({ fill: 'red', shape: 'dot', text: '오류 — 재시도 대기' });
return null;

// ================================================================
// 릴레이 전체 OFF — 자동매핑 버전 (2026-05-02)
// ================================================================
// "릴레이 초기화" 탭 → "릴레이 전체 OFF" 함수 노드 코드 전체 교체
//
// 변경: Waveshare/Eletechsup unit-id 하드코딩 (1, 2) → global.relayModules 동적
//   - 모듈 추가/삭제/unit-id 변경 시 별도 수정 불필요
//   - 어제 Waveshare unit-id 1→2 변경 후 OFF 명령이 unit 1 에 가던 버그 해결
// ================================================================

const relayModules = global.get('relayModules') || [];

if (!Array.isArray(relayModules) || relayModules.length === 0) {
    msg.payload = { success: false, detail: '등록된 릴레이 모듈 없음' };
    msg.statusCode = 400;
    node.send([null, msg]);
    node.warn('⚠️ 릴레이 전체 OFF: 등록된 모듈 없음');
    return null;
}

var results = [];
var commands = [];

for (const mod of relayModules) {
    const moduleType = (mod.moduleType || 'waveshare').toLowerCase();
    const channels = mod.channels || 8;

    if (moduleType === 'eletechsup') {
        // FC06 single write, 1-indexed register, value 512 = OFF (0x0200)
        for (let i = 1; i <= channels; i++) {
            commands.push({
                payload: { unitid: mod.unitId, fc: 6, address: i, value: 512, quantity: 1 },
                label: 'Eletechsup uid:' + mod.unitId + ' CH' + (i - 1),
            });
        }
    } else {
        // Waveshare FC15 multi-coil write, 0-indexed
        commands.push({
            payload: {
                unitid: mod.unitId,
                fc: 15,
                address: 0,
                quantity: channels,
                value: new Array(channels).fill(0),
            },
            label: (mod.name || 'Waveshare') + ' uid:' + mod.unitId + ' ' + channels + 'CH',
        });
    }
}

var sent = 0;
var total = commands.length;

function sendNext() {
    if (sent >= total) {
        msg.payload = {
            success: true,
            detail: total + '개 명령 전송',
            results: results,
        };
        msg.statusCode = 200;
        node.send([null, msg]);
        node.warn('🔄 릴레이 전체 OFF 완료: ' + total + '개 명령 (' + relayModules.length + ' 모듈)');
        return;
    }

    var cmd = commands[sent];
    var m = RED.util.cloneMessage(msg);
    m.payload = cmd.payload;
    results.push(cmd.label + ' → OFF');
    sent++;

    node.send([m, null]);

    if (sent < total) {
        setTimeout(sendNext, 200);
    } else {
        setTimeout(sendNext, 300);
    }
}

sendNext();
return null;

// ================================================================
// 릴레이 워치독 — houseConfig에서 모듈 자동 감지
// ================================================================
// 센서 폴링 완료 5초 후 실행 → RS-485 버스 충돌 없음
// 최소 60초 간격 보장 (센서 폴링이 더 잦아도 스킵)
// ================================================================

var lastCheck = context.get('lastCheck') || 0;
if (Date.now() - lastCheck < 55000) {
    return null;
}
context.set('lastCheck', Date.now());

var houseConfig = global.get('houseConfig');
var modules = [];
var seenUnits = {};

if (houseConfig && houseConfig.houses) {
    for (var i = 0; i < houseConfig.houses.length; i++) {
        var devices = houseConfig.houses[i].devices || [];
        for (var j = 0; j < devices.length; j++) {
            var mb = devices[j].modbus;
            if (!mb || !mb.unitId || seenUnits[mb.unitId]) continue;
            seenUnits[mb.unitId] = true;

            var mod = { unitId: mb.unitId, moduleType: mb.moduleType || 'waveshare' };

            if (mod.moduleType === 'waveshare') {
                mod.readFc = 1;  mod.readAddr = 0;
                mod.resetFc = 15; mod.resetAddr = 0; mod.resetQty = 8;
                mod.resetValue = [0,0,0,0,0,0,0,0];
            } else if (mod.moduleType === 'eletechsup') {
                mod.readFc = 3;  mod.readAddr = 1;
                mod.resetFc = 6; mod.resetAddr = 1; mod.resetQty = 1;
                mod.resetValue = 0;
            } else {
                mod.readFc = 1;  mod.readAddr = 0;
                mod.resetFc = 15; mod.resetAddr = 0; mod.resetQty = 8;
                mod.resetValue = [0,0,0,0,0,0,0,0];
            }
            modules.push(mod);
        }
    }
}

if (modules.length === 0) {
    node.status({fill:'grey', shape:'dot', text:'릴레이 모듈 없음'});
    return null;
}

global.set('_watchdogModules', modules);

// ★ 깨끗한 새 메시지 생성 (cloneMessage 제거)
var first = modules[0];
var msg1 = {
    payload: { unitid: first.unitId, fc: first.readFc, address: first.readAddr, quantity: 1 },
    _watchdog: { module: first.moduleType + '_' + first.unitId, unitId: first.unitId }
};

for (var k = 1; k < modules.length; k++) {
    (function(mod, idx) {
        setTimeout(function() {
            node.send({
                payload: { unitid: mod.unitId, fc: mod.readFc, address: mod.readAddr, quantity: 1 },
                _watchdog: { module: mod.moduleType + '_' + mod.unitId, unitId: mod.unitId }
            });
        }, idx * 3000);
    })(modules[k], k);
}

node.status({fill:'blue', shape:'dot', text: modules.length + '개 모듈 ' + new Date().toLocaleTimeString()});
return msg1;

// ================================================================
// 워치독 판정 — 실패 카운트 + 알림 + 복구
// ================================================================
var info = msg._watchdog;
if (!info) return null;

// stale 카운터 자가청소 — 모듈 교체(unitId 변경/제거) 시 옛 카운터 자동 정리
(function () {
    var currentModules = global.get('_watchdogModules') || [];
    var validKeys = {};
    currentModules.forEach(function (m) { validKeys[m.moduleType + '_' + m.unitId] = true; });
    var f = context.get('failures') || {};
    var a = context.get('alerts') || {};
    var n = context.get('lastNotified') || {};
    var cleaned = false;
    Object.keys(f).forEach(function (k) {
        if (!validKeys[k]) { delete f[k]; cleaned = true; }
    });
    Object.keys(a).forEach(function (k) { if (!validKeys[k]) delete a[k]; });
    Object.keys(n).forEach(function (k) { if (!validKeys[k]) delete n[k]; });
    if (cleaned) {
        context.set('failures', f);
        context.set('alerts', a);
        context.set('lastNotified', n);
        global.set('watchdogAlert', Object.keys(a).length > 0 ? a : null);
        node.warn('🧹 stale 카운터 정리됨');
    }
})();

var moduleName = info.module;
var ok = msg._watchdogOk;
var THRESHOLD = 3;

var modules = global.get('_watchdogModules') || [];
var moduleConfig = null;
for (var i = 0; i < modules.length; i++) {
    if (modules[i].moduleType + '_' + modules[i].unitId === moduleName) {
        moduleConfig = modules[i];
        break;
    }
}

var failures = context.get('failures') || {};
var alerts = context.get('alerts') || {};
var history = context.get('history') || [];

history.push({ module: moduleName, ok: ok, time: new Date().toISOString() });
if (history.length > 30) history = history.slice(-30);
context.set('history', history);

function updateGlobalStatus() {
    var status = {};
    modules.forEach(function(m) {
        var key = m.moduleType + '_' + m.unitId;
        status[key] = { ok: (failures[key] || 0) === 0, failCount: failures[key] || 0 };
    });
    status.lastCheck = new Date().toISOString();
    global.set('watchdogStatus', status);
}

function statusText() {
    return modules.map(function(m) {
        var key = m.moduleType + '_' + m.unitId;
        return m.moduleType.charAt(0).toUpperCase() + m.unitId + ':' + (failures[key] || 0);
    }).join(' ') + ' ' + new Date().toLocaleTimeString();
}

if (ok) {
    if ((failures[moduleName] || 0) > 0) {
        node.warn('✅ ' + moduleName + ' 복구됨 (이전 ' + failures[moduleName] + '회 실패)');
    }
    failures[moduleName] = 0;

    // 복구 시 조건 없이 global 갱신 — 노드 컨텍스트가 재시작에 사라져도 옛 경보(6/29)가 남지 않게
    delete alerts[moduleName];
    global.set('watchdogAlert', Object.keys(alerts).length > 0 ? alerts : null);

    context.set('failures', failures);
    context.set('alerts', alerts);
    updateGlobalStatus();
    node.status({ fill: 'green', shape: 'dot', text: statusText() });
    return [{ payload: '✅ ' + moduleName + ' 정상' }, null, null];
}

failures[moduleName] = (failures[moduleName] || 0) + 1;
node.warn('❌ ' + moduleName + ' 응답 없음 (' + failures[moduleName] + '회)');

context.set('failures', failures);
updateGlobalStatus();

if (failures[moduleName] < THRESHOLD) {
    node.status({ fill: 'yellow', shape: 'dot', text: statusText() });
    return [{ payload: '⚠️ ' + moduleName + ' 실패 ' + failures[moduleName] + '회' }, null, null];
}

var alertInfo = {
    module: moduleName,
    unitId: info.unitId,
    failCount: failures[moduleName],
    since: alerts[moduleName] ? alerts[moduleName].since : new Date().toISOString(),
    lastCheck: new Date().toISOString()
};
alerts[moduleName] = alertInfo;
context.set('alerts', alerts);
global.set('watchdogAlert', alerts);

node.warn('🚨 ' + moduleName + ' 장애! ' + failures[moduleName] + '회 — 복구 시도');

var recoveryMsg = null;
if (moduleConfig) {
    recoveryMsg = RED.util.cloneMessage(msg);
    recoveryMsg.payload = {
        value: moduleConfig.resetValue,
        unitid: moduleConfig.unitId,
        fc: moduleConfig.resetFc,
        address: moduleConfig.resetAddr,
        quantity: moduleConfig.resetQty
    };
}

node.status({ fill: 'red', shape: 'ring', text: '🚨 ' + statusText() });

return [
    { payload: '🚨 ' + moduleName + ' 장애 (' + failures[moduleName] + '회)' },
    recoveryMsg,
    { payload: alertInfo }
];

var alert = global.get('watchdogAlert') || null;
var status = global.get('watchdogStatus') || { lastCheck: null };

msg.payload = {
    status: status,
    alert: alert,
    timestamp: new Date().toISOString()
};
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// ================================================================
// MQTT 릴레이 조회 처리 — 등록된 모듈 자동 인식 (2026-05-01)
// ================================================================
// "Modbus 릴레이 읽기 + 응답" 함수 노드의 코드 전체 교체
//
// ⚠️ 기존 코드는 unitid:1, fc:1 (Waveshare) 하드코딩 → Eletechsup 등록 시 동작 안 함
// ✅ 새 코드는 "모듈 동기화" 탭이 PC 백엔드에서 받아 global 에 캐싱한 relayModules 사용
//
// 동작:
//   1. global.relayModules (modsync_handler 가 저장) 조회
//   2. 첫 모듈을 즉시 호출 (waveshare → FC1 coils, eletechsup → FC3 register)
//   3. 모듈이 여러 개면 1초 간격으로 순차 호출 (RS-485 충돌 방지)
//
// 출력:
//   1: Modbus 호출 (modbus-flex-getter)
//   2: (사용 안 함)
// ================================================================

let relayModules = global.get('relayModules');
if (!Array.isArray(relayModules)) relayModules = [];

// fallback: houseConfig.devices 에서 unit 추출 (모듈 동기화 미가동 시)
if (relayModules.length === 0) {
    const houseConfig = global.get('houseConfig');
    if (houseConfig && Array.isArray(houseConfig.houses)) {
        const seen = {};
        for (const h of houseConfig.houses) {
            for (const d of (h.devices || [])) {
                const mb = d.modbus;
                if (!mb || !mb.unitId || seen[mb.unitId]) continue;
                seen[mb.unitId] = true;
                relayModules.push({
                    unitId: mb.unitId,
                    moduleType: mb.moduleType || 'waveshare',
                    channels: 8,
                });
            }
        }
    }
}

if (relayModules.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: '등록 모듈 없음' });
    node.warn('relay/query: 등록된 릴레이 모듈이 없습니다');
    return null;
}

// ───────── 모듈별 Modbus 요청 생성 ─────────
function buildModbusMsg(mod) {
    const moduleType = (mod.moduleType || 'waveshare').toLowerCase();
    if (moduleType === 'eletechsup') {
        // FC3 (Read Holding Registers), 1-indexed (channel 1..N)
        return {
            payload: {
                unitid: mod.unitId,
                fc: 3,
                address: 1,
                quantity: mod.channels || 8,
            },
            topic: 'relay_query',
            _module: { unitId: mod.unitId, moduleType: 'eletechsup', channels: mod.channels || 8 },
        };
    }
    // 기본: Waveshare (FC1 Read Coils, 0-indexed)
    return {
        payload: {
            unitid: mod.unitId,
            fc: 1,
            address: 0,
            quantity: mod.channels || 8,
        },
        topic: 'relay_query',
        _module: { unitId: mod.unitId, moduleType: 'waveshare', channels: mod.channels || 8 },
    };
}

const first = buildModbusMsg(relayModules[0]);

// 나머지 모듈은 1초 간격으로 순차 발송 (RS-485 충돌 회피)
for (let i = 1; i < relayModules.length; i++) {
    (function (mod, idx) {
        setTimeout(function () {
            node.send([buildModbusMsg(mod), null]);
        }, idx * 1000);
    })(relayModules[i], i);
}

node.status({ fill: 'blue', shape: 'dot', text: relayModules.length + '개 모듈 query ' + new Date().toLocaleTimeString() });
return [first, null];

// Modbus 읽기 결과 → MQTT 응답 포맷
const farmId = global.get('houseConfig')?.farmId 
            || global.get('farmId') 
            || env.get('FARM_ID') 
            || 'farm_0001';

// buildModbusMsg 가 _module 에 박아둔 unit 정보 사용 (unit=2 Waveshare)
const mod = msg._module || {};
const unitId = mod.unitId || (msg.payload && msg.payload.unitid) || 2;
const moduleType = mod.moduleType || 'waveshare';

const coils = {};
if (msg.payload && Array.isArray(msg.payload)) {
    msg.payload.forEach((val, idx) => {
        coils[idx] = !!val;
    });
}

msg.topic = `smartfarm/${farmId}/relay/response`;
msg.payload = {
    farmId,
    unitId,
    moduleType,
    coils,
    timestamp: new Date().toISOString()
};

node.warn(`📡 릴레이 상태 MQTT 발행 (unit=${unitId}/${moduleType}): ${JSON.stringify(coils)}`);
return msg;

// 제어 실행 완료 후 릴레이 상태를 MQTT로 발행
// ★ SW mutex 로 RS-485 write-read race 차단 + Waveshare-only 단순화

const farmId = global.get('houseConfig')?.farmId
            || global.get('farmId')
            || env.get('FARM_ID')
            || 'farm_0001';

// unitId 동적 추출 — relayModules 캐시에서 Waveshare 의 실제 unitId
const modules = global.get('relayModules') || [];
const unitId = (modules[0] && modules[0].unitId) || 2;

// ★ mutex 파라미터
const SAFE_GAP_MS = 500;       // write 완료 후 read 까지 최소 gap
const MAX_WAIT_MS = 3000;
const POLL_INTERVAL_MS = 100;

function fireRead() {
    node.send({
        payload: { unitid: unitId, fc: 1, address: 0, quantity: 8 },   // Waveshare FC1
        topic: 'relay_status_after_control',
        _module: { unitId: unitId, moduleType: 'waveshare' }
    });
    node.warn('🔄 제어 후 상태 읽기 발사: uid=' + unitId + ' gap=' + (Date.now() - (global.get('_modbusLastWriteAt') || 0)) + 'ms');
}

var elapsed = 0;
function tryFire() {
    var lastWriteAt = global.get('_modbusLastWriteAt') || 0;
    var sinceLastWrite = Date.now() - lastWriteAt;

    if (sinceLastWrite >= SAFE_GAP_MS) {
        fireRead();
        return;
    }
    if (elapsed >= MAX_WAIT_MS) {
        node.warn('⚠️ 제어 후 상태 발행: mutex 대기 타임아웃 (sinceWrite=' + sinceLastWrite + 'ms) — 강제 발사');
        fireRead();
        return;
    }
    var wait = Math.min(POLL_INTERVAL_MS, SAFE_GAP_MS - sinceLastWrite);
    elapsed += wait;
    setTimeout(tryFire, wait);
}

// ★ 초기 안전 delay 800ms — 거의 모든 경우 즉시 fireRead, mutex drift 흡수
setTimeout(tryFire, 800);
return null;

// MQTT로 수신한 autoDevices를 global context에 저장
// 다중 하우스: 'houseId:deviceId' 복합키로 정규화한다.
// backend 는 payload 에 houseId 를 함께 발행한다 (automation.routes.js PUT /:farmId/active)
const data = msg.payload;
if (data && data.action === 'set_autoDevices') {
    const dkey = global.get('dkey') || function (h, dv) { return (h || 'house_0001') + ':' + dv; };
    const hId = (data.houseId && data.houseId !== 'all') ? data.houseId : 'house_0001';
    const incoming = (data.autoDevices || []).map(function (x) {
        const v = String(x);
        return v.indexOf(':') > -1 ? v : dkey(hId, v);
    });

    // 해당 하우스 항목만 교체하고 다른 하우스 설정은 보존
    const prev = global.get('autoDevices') || [];
    const kept = prev.filter(function (k) { return String(k).indexOf(hId + ':') !== 0; });
    const merged = kept.concat(data.active === false ? [] : incoming);

    global.set('autoDevices', merged);
    node.warn('📡 autoDevices 업데이트 (MQTT, ' + hId + '): ' + JSON.stringify(merged));

    // 자동화 규칙 재로드 트리거
    return { payload: 'reload', topic: 'autoDevices_updated' };
}
return null;

const data = msg.payload;
const action = data.action;

node.warn('🔧 시스템 명령 수신: ' + action + ' (by ' + (data.operator || 'unknown') + ')');

if (action === 'restart-nodered') {
    msg.payload = 'pm2 restart node-red';
    return msg;
} else if (action === 'restart-rpi-express' || action === 'restart-express') {
    msg.payload = 'pm2 restart smartfarm-rpi';
    return msg;
} else {
    node.warn('⚠️ 알 수 없는 시스템 명령: ' + action);
    return null;
}

// ================================================================
// modsync_trigger — 백엔드 system-settings GET 요청 준비 (2026-05-01 final)
// ================================================================
// "모듈 동기화" 탭 → "백엔드 API 호출 준비" 함수 노드 코드 전체 교체
//
// 캐시 무력화: _t 쿼리 파라미터 + no-cache 헤더 (Cloudflare/Node-RED HTTP 캐시 회피)
// ================================================================

const farmId = global.get('farmId') || env.get('FARM_ID') || 'farm_0001';
const pcServer = global.get('pcServerUrl') || 'https://api.smartgreen.kr';
const apiKey = env.get('SENSOR_API_KEY') || global.get('sensorApiKey') || '';
const source = msg.topic === 'scheduled_sync' ? '검증' : '즉시';

msg.method = 'GET';
msg.url = pcServer + '/api/config/system-settings/' + farmId + '?_t=' + Date.now();
msg.headers = {
