}

const houses = (payload && payload.success && Array.isArray(payload.data)) ? payload.data : [];
if (houses.length === 0) {
    node.warn('houseConfig 빈 응답 — refresh 안 함');
    return null;
}

const farmId = msg._farmId || 'farm_0001';
const eventType = msg._eventType || '?';

// 기존 houseConfig 와 비교
const prev = global.get('houseConfig') || {};
const prevHouses = prev.houses || [];

// houseConfig 구조 (워치독/sensor 폴링이 사용하는 형식)
const newHouseConfig = {
    farmId,
    houses: houses.map(h => ({
        id: h.houseId,
        houseId: h.houseId,
        name: h.houseName || h.name,
        enabled: h.enabled !== false,
        sensors: h.sensors || [],
        devices: h.devices || [],
        configVersion: h.configVersion || 0,
    })),
    configVersion: Math.max(0, ...houses.map(h => h.configVersion || 0)),
};

global.set('houseConfig', newHouseConfig);
global.set('houseConfigUpdatedAt', new Date().toISOString());

// 워치독 캐시 무효화 (modules 변경 시 워치독이 옛 sensor 폴링 안 하도록)
global.set('_watchdogModules', null);

const sensorTotal = houses.reduce((sum, h) => sum + (h.sensors?.length || 0), 0);
const deviceTotal = houses.reduce((sum, h) => sum + (h.devices?.length || 0), 0);

node.status({
    fill: 'green', shape: 'dot',
    text: eventType + ' H:' + houses.length + ' S:' + sensorTotal + ' D:' + deviceTotal
});
node.warn('🏠 houseConfig refresh (' + eventType + '): ' + houses.length + ' houses, ' + sensorTotal + ' sensors, ' + deviceTotal + ' devices');

return null;

// config/update 는 한 곳에서만 구독한다 (2026-08-28). 전에는 mqtt in 두 개가 같은 토픽을 받아
// 설정 변경 한 번에 system-settings GET 이 두 번 나갔다(house_* 이벤트에도).
let data = msg.payload;
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { node.warn('config/update JSON 파싱 실패: ' + e.message); return null; } }
if (!data || typeof data !== 'object') return null;
msg.payload = data;
const type = String(data.type || '');
if (type.startsWith('house_')) return [null, msg];   // → houseConfig refresh
return [msg, null];                                   // modules_changed 등 → system-settings

// global.sensorModules 의 모든 모듈을 sequential read
// Waveshare relay/query 와 동일 패턴 — RS-485 충돌 회피 위해 1초 간격 발사

const farmId = global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';
const sensorModules = global.get('sensorModules') || [];

if (!Array.isArray(sensorModules) || sensorModules.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: '등록 모듈 없음' });
    node.warn('sensor/query: 등록된 센서 모듈이 없습니다');
    return null;
}

function buildMsg(mod) {
    return {
        payload: {
            unitid: mod.unitId,
            fc: mod.fc || 3,
            address: mod.address || 0,
            quantity: mod.quantity || 1,
        },
        topic: 'sensor_query',
        _module: {
            unitId: mod.unitId,
            fc: mod.fc || 3,
            address: mod.address || 0,
            quantity: mod.quantity || 1,
            divider: mod.divider || 1,
            signed: mod.signed || false,
            sensorType: mod.sensorType,
            farmId: farmId,
        },
    };
}

const first = buildMsg(sensorModules[0]);

// 나머지 모듈 1초 간격으로 순차 발송
for (let i = 1; i < sensorModules.length; i++) {
    (function (mod, idx) {
        setTimeout(function () {
            node.send(buildMsg(mod));
        }, idx * 1000);
    })(sensorModules[i], i);
}

node.status({ fill: 'blue', shape: 'dot', text: sensorModules.length + '개 모듈 query ' + new Date().toLocaleTimeString() });
return first;

// modbus-flex-getter 응답 → MQTT smartfarm/{farmId}/sensor/status
// payload.responseBuffer.data: 16-bit register 배열

const mod = msg._module || {};
const farmId = mod.farmId || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

const raw = (msg.payload && Array.isArray(msg.payload)) ? msg.payload
           : (msg.payload && msg.payload.data) ? msg.payload.data
           : (msg.responseBuffer && msg.responseBuffer.data) ? msg.responseBuffer.data
           : [];

if (!Array.isArray(raw) || raw.length === 0) {
    node.warn('sensor/query: empty raw — unitId=' + mod.unitId);
    return null;
}

msg.topic = 'smartfarm/' + farmId + '/sensor/status';
msg.payload = {
    unitId: mod.unitId,
    fc: mod.fc,
    address: mod.address,
    quantity: mod.quantity,
    raw: raw,
    divider: mod.divider,
    signed: mod.signed,
    sensorType: mod.sensorType,
    timestamp: new Date().toISOString(),
};
msg.qos = 1;
msg.retain = false;

node.status({ fill: 'green', shape: 'dot', text: 'unit ' + mod.unitId + ': ' + raw.slice(0,2).join(',') });
return msg;

// RPi Express (smartfarm-rpi, port 3001 또는 1880 nginx) 의 /api/sync/status 호출
