msg.payload = null;

node.status({ fill: 'blue', shape: 'dot', text: 'GET ' + farmId });
return msg;

// HTTP 응답 → MQTT smartfarm/{farmId}/sync/status
const farmId = msg._farmId || 'farm_0001';

let data = msg.payload;
if (typeof data === 'string') {
