} else {
    node.warn('sync/' + action + ' 실패: ' + farmId + ' status=' + msg.statusCode);
}

// 명령 후 status 자동 갱신을 위해 sync/query 트리거 (1초 대기)
setTimeout(function() {
    node.send({
        method: 'GET',
        url: 'http://localhost:1880/api/sync/status',
        headers: { 'Content-Type': 'application/json' },
        payload: null,
        _farmId: farmId,
    });
}, 1000);

return null;

// MQTT 토픽에서 farmId 추출하여 보존 (응답에 포함)
const topicParts = (msg.topic || '').split('/');
const farmId = topicParts[1] || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

msg._farmId = farmId;
msg.payload = '';  // exec 노드 입력은 빈 문자열 (command 자체에 인자 없음)

node.status({ fill: 'blue', shape: 'dot', text: 'pm2 jlist ' + farmId });
return msg;

// pm2 jlist 의 stdout (JSON 배열) 파싱 후 process 별 status 추출
const farmId = msg._farmId || 'farm_0001';

let processes = [];
try {
    processes = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    if (!Array.isArray(processes)) processes = [];
} catch (e) {
    node.warn('pm2 jlist 파싱 실패: ' + e.message);
    return null;
}

function extract(name) {
    const p = processes.find(x => x.name === name);
    if (!p) return null;
    const env = p.pm2_env || {};
    return {
        status: env.status || 'unknown',
        uptime: env.pm_uptime || null,  // ms epoch (start time)
        restarts: env.restart_time || 0,
        unstableRestarts: env.unstable_restarts || 0,
        pid: p.pid || null,
        memory: p.monit?.memory || 0,
        cpu: p.monit?.cpu || 0,
    };
}

const status = {
    nodeRed: extract('node-red'),
    rpiExpress: extract('smartfarm-rpi'),
    smartfarmSystem: extract('smartfarm-system'),
};

msg.topic = 'smartfarm/' + farmId + '/system/status';
msg.payload = {
    ...status,
    farmId,
    timestamp: new Date().toISOString(),
};
msg.qos = 1;
msg.retain = false;

const nrUp = status.nodeRed?.status === 'online' ? '✓' : '✗';
const expUp = status.rpiExpress?.status === 'online' ? '✓' : '✗';
node.status({
    fill: 'green', shape: 'dot',
    text: 'NR:' + nrUp + ' EXP:' + expUp + ' (' + new Date().toLocaleTimeString() + ')'
});
return msg;

// ───────────────────────────────────────────
// GlitchTip Sentry Envelope (v7) 생성
// ───────────────────────────────────────────
const SENTRY_KEY = 'eb89cdc6d3fe4ddbbec47f5e17a486c0';
const PROJECT_ID = '3';
const FARM_ID = env.get('FARM_ID') || os.hostname();

// catch 가 잡은 실제 에러, 또는 inject 테스트용 인공 에러
const isTest = msg._test_glitchtip === true;
const err = msg.error || (isTest ? {
    message: 'TEST: Node-RED → GlitchTip ' + new Date().toISOString(),
    source: { type: 'inject', name: '수동 테스트', id: 'gt_test_inject', z: 'glitchtip_flow' },
    stack: ''
} : { message: String(msg.payload || 'unknown'), source: {} });

const src = err.source || {};
const timestamp = Date.now() / 1000;

// 16바이트 랜덤 hex (crypto.randomBytes 대체)
let eventId = '';
for (let i = 0; i < 32; i++) eventId += Math.floor(Math.random() * 16).toString(16);

function parseStack(stack) {
    if (!stack) return [];
    return stack.split('\n').slice(1, 11).map(line => {
        const m = line.match(/at\s+(.+?)\s+\((.+?):(\d+):(\d+)\)/) || line.match(/at\s+(.+?):(\d+):(\d+)/);
        if (!m) return { function: line.trim(), filename: '?', lineno: 0 };
        return m.length === 5
            ? { function: m[1], filename: m[2], lineno: parseInt(m[3]), colno: parseInt(m[4]) }
            : { function: '<anonymous>', filename: m[1], lineno: parseInt(m[2]), colno: parseInt(m[3]) };
    });
}

const event = {
    event_id: eventId,
    timestamp: timestamp,
    platform: 'node',
    level: 'error',
    logger: 'node-red',
    server_name: os.hostname(),
    environment: 'production',
    tags: {
        service: 'node-red',
        farm_id: FARM_ID,
        node_type: src.type || 'unknown',
        node_name: src.name || src.id || 'unnamed',
        flow_id: src.z || 'unknown',
        test: isTest ? 'true' : 'false'
    },
    message: { formatted: err.message || 'unknown error' },
    exception: {
        values: [{
            type: err.name || (isTest ? 'NodeRedTest' : 'NodeRedError'),
            value: err.message || String(err),
            stacktrace: { frames: parseStack(err.stack) }
        }]
    },
    extra: {
        msg_topic: msg.topic || null,
        msg_payload: typeof msg.payload === 'object' ? JSON.stringify(msg.payload).slice(0, 500) : String(msg.payload || '').slice(0, 500),
        source_node: src
    }
};

const envelopeHeader = JSON.stringify({ event_id: eventId, sent_at: new Date().toISOString() });
const itemHeader = JSON.stringify({ type: 'event', content_type: 'application/json' });
const itemPayload = JSON.stringify(event);

msg.payload = envelopeHeader + '\n' + itemHeader + '\n' + itemPayload;
msg.headers = {
    'Content-Type': 'application/x-sentry-envelope',
    'X-Sentry-Auth': 'Sentry sentry_version=7, sentry_key=' + SENTRY_KEY + ', sentry_client=node-red/1.0'
};
msg.url = 'https://sentry.smartgreen.kr/api/' + PROJECT_ID + '/envelope/';

node.warn('envelope 생성 완료: ' + (isTest ? 'TEST' : 'caught'));
node.status({ fill: 'blue', shape: 'dot', text: 'sent (' + (isTest ? 'TEST' : 'caught') + ')' });
return msg;

global.set('nutrientSimulator', msg.payload);
node.warn('simulator = ' + msg.payload);
return null;

// 양액 시뮬레이터 — 하드웨어 도착 전 가상 EC/pH/유량 생성
// 입력: timestamp inject (5초 주기)
// 출력: msg.payload = { ec, ph, flow, temperature, timestamp }
//
// 활성화: global.set('nutrientSimulator', true)
// 비활성화 시 (실 센서 사용): return null

const enabled = global.get('nutrientSimulator');
if (!enabled) return null;

// 메인 펌프 상태 (다른 플로우에서 set)
const pumpOn = global.get('mainPumpOn') || false;

// 안정 상태 기준값 (시나리오 active 시 그 ecTarget 근처로 수렴)
const activeScenario = global.get('activeScenario') || {};
const ecTarget = activeScenario.ecTarget || 2.0;
const phTarget = activeScenario.phTarget || 6.0;

// 이전 값 (천천히 변동)
let prev = context.get('lastReading') || { ec: ecTarget, ph: phTarget };

// 작은 노이즈 + 타겟 수렴
const drift = (target, current, noise) => {
    const towards = (target - current) * 0.1;
    const random = (Math.random() - 0.5) * noise;
    return +(current + towards + random).toFixed(3);
};

const reading = {
    ec: drift(ecTarget, prev.ec, 0.05),
    ph: drift(phTarget, prev.ph, 0.03),
    temperature: +(22 + (Math.random() - 0.5) * 2).toFixed(1),
    flow: pumpOn ? +(8 + (Math.random() - 0.5) * 0.5).toFixed(2) : 0,
    timestamp: new Date().toISOString(),
    source: 'simulator',
};

context.set('lastReading', reading);
msg.payload = reading;

// 상태 표시용 노드 메시지
node.status({ fill: 'blue', shape: 'dot', text: `EC ${reading.ec} · pH ${reading.ph}` });

return msg;

// 양액 안전 인터락 — 한계 초과 시 모드 강제 변경 + 릴레이 OFF
// 입력: msg.payload = { ec, ph, flow, ... } (telemetry 와 동일)
// 출력 1: 정상 → 다음 노드로 통과
// 출력 2: 비상 발생 → 모든 릴레이 OFF + 경보 POST
//
// 우선순위: 비상정지/누액 > EC critical > pH critical > 탱크부족 > 센서오류

const r = msg.payload;
if (!r) return null;

// 기존 NR 패턴 — sensorApiKey + FARM_ID 환경변수 fallback
const farmId = global.get('FARM_ID') || 'farm_0001';
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';
const config = global.get('nutrientConfig') || {};
const alerts = config.alerts || { ecUpper: 4.0, ecCritical: 0.1, phUpper: 8.0, phCritical: 6.5 };
const activeScenario = global.get('activeScenario') || {};

// ⭐ 히스테리시스 + 다량공급 — cycle-runner 가 dosingMode 참조
// 목표값 ± hysteresis 범위 안이면 도싱 안 함 (펌프 hunting 방지)
// 목표 ± deviation 이상 차이면 빠른 보정 (다량공급)
const ecHyst = alerts.ecHysteresis ?? 0.1;
const phHyst = alerts.phHysteresis ?? 0.1;
const ecDev = alerts.ecDeviation ?? 0.5;
const phDev = alerts.phDeviation ?? 0.5;

if (activeScenario.ecTarget != null && r.ec != null) {
    const gap = r.ec - activeScenario.ecTarget;
    let mode;
    if (Math.abs(gap) <= ecHyst) mode = 'idle';
    else if (Math.abs(gap) >= ecDev) mode = gap < 0 ? 'fast_up' : 'fast_down';
    else mode = gap < 0 ? 'normal_up' : 'normal_down';
    global.set('ecDosingMode', mode);
}
if (activeScenario.phTarget != null && r.ph != null) {
    const gap = r.ph - activeScenario.phTarget;
    let mode;
    if (Math.abs(gap) <= phHyst) mode = 'idle';
    else if (Math.abs(gap) >= phDev) mode = gap > 0 ? 'fast_acid' : 'fast_alkali';
    else mode = gap > 0 ? 'normal_acid' : 'normal_alkali';
    global.set('phDosingMode', mode);
}

const triggered = []; // { type, severity, value, threshold, message, action }

// 1. 비상정지 GPIO (다른 플로우에서 set)
if (global.get('emergencyStop')) {
    triggered.push({
        type: 'emergency_stop',
        severity: 'critical',
        message: '비상정지 버튼 활성화',
        action: '전체 릴레이 OFF · 수동 복구 필요',
    });
}

// 2. 누액 GPIO
if (global.get('leakDetected')) {
    triggered.push({
        type: 'leak_detected',
        severity: 'critical',
        message: '누액 감지',
        action: '전체 릴레이 OFF',
    });
}

// 3. EC 상한 초과
if (r.ec != null && r.ec > alerts.ecUpper) {
    triggered.push({
        type: 'ec_upper',
        severity: r.ec > alerts.ecUpper * 1.2 ? 'critical' : 'warning',
        value: r.ec,
        threshold: alerts.ecUpper,
        message: `EC ${r.ec} > 상한 ${alerts.ecUpper}`,
        action: '도싱 정지 · 원수 보충 필요',
    });
}

// 4. EC critical 미달 (센서 오류·미연결)
if (r.ec != null && r.ec < alerts.ecCritical) {
    triggered.push({
        type: 'ec_critical_low',
        severity: 'critical',
        value: r.ec,
        threshold: alerts.ecCritical,
        message: `EC ${r.ec} 비정상 (센서 오류 가능)`,
        action: '제어 정지 · 센서 점검',
    });
}

// 5. pH 범위 이탈
if (r.ph != null && (r.ph > alerts.phUpper || r.ph < alerts.phLower)) {
    triggered.push({
        type: r.ph > alerts.phUpper ? 'ph_upper' : 'ph_lower',
        severity: 'warning',
        value: r.ph,
        threshold: r.ph > alerts.phUpper ? alerts.phUpper : alerts.phLower,
        message: `pH ${r.ph} 범위 이탈`,
        action: r.ph > alerts.phUpper ? '산 도싱 +' : '알칼리 도싱 +',
    });
}

// 6. 센서 통신 오류 (30초 이상 telemetry 없음) — simulator 모드에선 스킵
if (!global.get('nutrientSimulator')) {
    const lastTel = global.get('lastTelemetry');
    if (lastTel && (Date.now() - lastTel.at) > 30000) {
        triggered.push({
            type: 'sensor_timeout',
            severity: 'critical',
            message: '센서 통신 30초 이상 끊김',
            action: '모드 paused · 센서 점검',
        });
    }
}

// === 우선순위 처리 ===
const criticalHit = triggered.find(t => t.severity === 'critical');

if (criticalHit) {
    // 양액 채널만 OFF (32CH 통합: 환경 0~7 유지, 양액 8~31 차단)
    // 환경 채널을 끄면 측창·팬·LED 등 정상 운영 중단 → 양액만 분리 차단
    global.set('safetyStop', true);
    global.set('emergencyReason', criticalHit.type);

    // modbus-flex-write 호환: FC15 = Write Multiple Coils
    // address=8, quantity=24 → 채널 8~31 (양액 24채널) 모두 OFF
    const offCmd = {
        payload: {
            value: Array(24).fill(false),
            fc: 15,
            unitid: 3,
            address: 8,
            quantity: 24,
        },
        reason: criticalHit.message,
    };
    node.status({ fill: 'red', shape: 'ring', text: `🛑 ${criticalHit.type}` });

    // backend 경보 POST 메시지
    const alertMsg = {
        url: `https://api.smartgreen.kr/internal/nutrient/alerts`,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
        },
        payload: criticalHit,
    };
    return [null, [offCmd, alertMsg]];
}

// warning 만 있으면 경보만 POST, 사이클은 계속
if (triggered.length > 0) {
    node.status({ fill: 'yellow', shape: 'dot', text: `⚠️ ${triggered[0].type}` });
    const alertMsgs = triggered.map(t => ({
        url: `https://api.smartgreen.kr/internal/nutrient/alerts`,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
        },
        payload: t,
    }));
    return [msg, alertMsgs];
}

// 정상
global.set('safetyStop', false);
node.status({ fill: 'green', shape: 'dot', text: '✓ OK' });
return [msg, null];

// 양액 telemetry publisher — EC/pH/유량 값을 backend 에 POST
// 입력: msg.payload = { ec, ph, flow, temperature, timestamp }
// 출력: HTTP request 노드로 전달
//
// backend: PUT /internal/nutrient/state/telemetry (farmId 는 x-api-key 로 식별)
// body: { ecCurrent, phCurrent, solarAccumulated?, currentCycle? }

const r = msg.payload;
if (!r || typeof r !== 'object') return null;

// 기존 NR 패턴 — sensorApiKey + FARM_ID 환경변수 fallback
const farmId = global.get('FARM_ID') || 'farm_0001';
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';

// 일사량 적산 (solar 기반 시나리오용) — 별도 inject 또는 weather 노드에서 set
const solarAccumulated = global.get('solarAccumulated') || 0;

// 현재 사이클 (cycle-runner 가 set 한 값)
const currentCycle = global.get('currentCycle') || null;

// telemetry 페이로드
const body = {
    ecCurrent: r.ec,
    phCurrent: r.ph,
    solarAccumulated,
};
if (currentCycle) body.currentCycle = currentCycle;

// HTTP request 노드용 msg 구성
msg.url = `https://api.smartgreen.kr/internal/nutrient/state/telemetry`;
msg.method = 'PUT';
msg.headers = {
    'Content-Type': 'application/json',
    'x-api-key': apiKey,
};
msg.payload = body;

// 메인 펌프 상태 추적 (시뮬레이터에 피드백)
global.set('lastTelemetry', { ec: r.ec, ph: r.ph, at: Date.now() });

node.status({ fill: 'green', shape: 'dot', text: `PUT EC ${r.ec}` });

return msg;

// 양액 시나리오 트리거 평가 — 1분 주기 inject
// 입력: timestamp
// 출력 1: 트리거 발생 → cycle-runner 로 시나리오 전달
// 출력 2: 트리거 없음 (null)
//
// backend 에서 active 시나리오 + state 가져와 평가
// irrigationMode 별 판단:
//   solar    → solarAccumulated >= solarThreshold
//   timer    → 마지막 사이클로부터 timerInterval 경과
//   schedule → 현재 시각이 scheduleSlots 중 하나와 매칭 (HH:MM, ±1분)

const farmId = global.get('FARM_ID') || 'farm_0001';

// 안전 정지 상태면 트리거 안 함
if (global.get('safetyStop')) {
    node.status({ fill: 'red', shape: 'ring', text: '🛑 safetyStop' });
    return [null, null];
}

// 진행 중 사이클 있으면 새로 트리거 안 함
if (global.get('cycleInProgress')) {
    node.status({ fill: 'blue', shape: 'dot', text: '⏳ 사이클 진행 중' });
    return [null, null];
}

// 백엔드에서 받아온 시나리오·상태는 별도 inject 가 5분마다 fetch 해서 global 에 저장
//   global.activeScenario  = { id, irrigationMode, ecTarget, ..., valves, days }
//   global.state           = { mode, solarAccumulated, ... }
//   global.lastCycleAt     = timestamp (사이클 완료 시 set)

const scenario = global.get('activeScenario');
const state = global.get('state') || {};

if (!scenario) {
    node.status({ fill: 'grey', shape: 'ring', text: 'active 시나리오 없음' });
    return [null, null];
}

// 모드 체크 — auto 일 때만 자동 트리거
if (state.mode !== 'auto') {
    node.status({ fill: 'grey', shape: 'ring', text: `mode=${state.mode}` });
    return [null, null];
}

// 요일 체크
const now = new Date();
const dayOfWeek = now.getDay(); // 0=일, 6=토
if (Array.isArray(scenario.days) && scenario.days.length > 0 && !scenario.days.includes(dayOfWeek)) {
    node.status({ fill: 'grey', shape: 'ring', text: '오늘 요일 X' });
    return [null, null];
}

// 시간 범위 체크 (timer/schedule 모드만)
const hhmm = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
const inTimeRange = (start, end) => {
    if (!start || !end) return true;
    if (start <= end) return hhmm >= start && hhmm <= end;
    return hhmm >= start || hhmm <= end; // 자정 넘기기
};

let shouldTrigger = false;
let reason = '';

if (scenario.irrigationMode === 'solar') {
    // ⭐ 최소 일사량 체크 — 현재 일사량이 기준 미만이면 적산 중단·트리거 무시
    const config = global.get('nutrientConfig') || {};
    const minSolar = config.alerts?.minSolarWm2 ?? 50;
    const currentSolar = global.get('currentSolarWm2') || 0;
    if (currentSolar < minSolar) {
        node.status({ fill: 'grey', shape: 'ring', text: `흐림 ${currentSolar}<${minSolar} W/m²` });
        return [null, null];
    }
    // 일사량 적산 도달 시
    if ((state.solarAccumulated || 0) >= (scenario.solarThreshold || 100)) {
        shouldTrigger = true;
        reason = `solar ${state.solarAccumulated}/${scenario.solarThreshold} W/m²`;
        // 트리거 후 적산 리셋 — global + backend DB 둘 다.
        // 이전: global.set 만 호출 → 다음 telemetry fetch 까지 옛 값 유지되어 즉시 재트리거 가능.
        global.set('solarAccumulated', 0);
        // backend telemetry PUT 으로 DB 도 0 으로 동기화
        const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';
        node.send([null, null, {
            url: `https://api.smartgreen.kr/internal/nutrient/state/telemetry`,
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', 'x-api-key': apiKey },
            payload: { solarAccumulated: 0 },
        }]);
    }
} else if (scenario.irrigationMode === 'timer') {
    if (!inTimeRange(scenario.timerStart, scenario.timerEnd)) {
        node.status({ fill: 'grey', shape: 'ring', text: '시간 범위 밖' });
        return [null, null];
    }
    // 마지막 사이클 + interval 경과?
    const lastAt = global.get('lastCycleAt') || 0;
    const intervalMin = parseTimeToMinutes(scenario.timerInterval || '00:30');
    if (Date.now() - lastAt >= intervalMin * 60 * 1000) {
        shouldTrigger = true;
        reason = `timer 경과 ${intervalMin}분`;
    }
} else if (scenario.irrigationMode === 'schedule') {
    if (Array.isArray(scenario.scheduleSlots) && scenario.scheduleSlots.includes(hhmm)) {
        // 같은 슬롯 중복 방지 — 1분 윈도우 안에 한 번만
        const lastSlot = global.get('lastTriggeredSlot');
        if (lastSlot !== `${now.toDateString()}@${hhmm}`) {
            shouldTrigger = true;
            reason = `schedule ${hhmm}`;
            global.set('lastTriggeredSlot', `${now.toDateString()}@${hhmm}`);
        }
    }
}

if (shouldTrigger) {
    node.status({ fill: 'green', shape: 'dot', text: `▶ ${reason}` });
    return [{
        payload: {
            scenarioId: scenario.id,
            scenario,
            triggeredAt: now.toISOString(),
            reason,
        },
    }, null];
}

node.status({ fill: 'grey', shape: 'dot', text: '대기' });
return [null, null];

// HH:MM → 분 단위 변환
function parseTimeToMinutes(t) {
    if (!t) return 30;
    const [h, m] = t.split(':').map(Number);
    return (h || 0) * 60 + (m || 0);
}

// 양액 1회 관수 사이클 실행 — trigger-evaluator 에서 발사
// 입력: msg.payload = { scenarioId, scenario, triggeredAt, reason }
// 출력 1: Modbus 릴레이 명령 (Unit-Id 3 FC15)
// 출력 2: backend telemetry/counters POST 메시지
//
// Phase: 도싱 → 교반 → 안정화 → 관수 (구역 순차) → 정리
// 비동기 단계라서 setTimeout 으로 처리. 각 단계마다 currentCycle 갱신.

// 기존 NR 패턴 — sensorApiKey + FARM_ID 환경변수 fallback
const farmId = global.get('FARM_ID') || 'farm_0001';
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';
const config = global.get('nutrientConfig') || {};

if (global.get('cycleInProgress')) {
    node.warn('이미 사이클 진행 중 — 새 트리거 무시');
    return null;
}
if (global.get('safetyStop')) {
    node.warn('safetyStop 활성 — 사이클 시작 불가');
    return null;
}

const scenario = msg.payload.scenario;
const tanks = config.tanks || [];
const valveCount = config.valveCount || 14;
const hw = config.hardware || { dosingPulseUnit: 500 };

// 수동 작업 (manual-job-poller 가 forward) 인식 — backend status 동기화에 사용
const manualJobId = msg.payload.manualJobId || null;
const manualValves = Array.isArray(msg.payload.valves) ? msg.payload.valves : null;
const manualVolumeML = msg.payload.volumeML ?? null;

// 사이클 ID + 시작 시각
const cycleId = `cycle-${Date.now()}`;
const startedAt = new Date().toISOString();

global.set('cycleInProgress', true);
global.set('currentCycle', {
    id: cycleId,
    scenarioId: scenario.id,
    manualJobId,
    startedAt,
    phase: 'dosing',
    suppliedL: 0,
    valveIdx: -1,
});

node.status({ fill: 'blue', shape: 'dot', text: manualJobId ? `✋ ${cycleId.slice(-6)}` : `▶ ${cycleId.slice(-6)}` });

// 수동 작업이면 backend 에 status=running 통보 (시작 알림)
if (manualJobId) {
    sendBackend('PUT', `/manual-jobs/${manualJobId}/status`, { status: 'running' });
}

// === Phase 1: 도싱 (각 탱크 dosingRatio × baseVolume) ===
// baseVolume = 메인탱크 부피 (예: 100L) 의 도싱 비율로 mL 산출
// 수동 작업 시 manualVolumeML override 사용
const BASE_VOLUME_ML = manualVolumeML != null ? manualVolumeML : 100 * 1000; // default 100L
const dosingRatio = scenario.dosingRatio || {};

// ⭐ 산/알칼리 운영 모드 — 'both' | 'acid' | 'alkali'
const acidAlkaliMode = hw.acidAlkaliMode || 'both';

// ⭐ 다량공급 boost factor — safety-interlock 이 set 한 dosingMode 기반
const ecMode = global.get('ecDosingMode') || 'normal_up';
const phMode = global.get('phDosingMode') || 'normal_acid';
const isFast = ecMode.startsWith('fast') || phMode.startsWith('fast');
const boost = isFast ? 2.0 : 1.0;  // 빠른 모드면 2배 도싱

// 도싱 펌프 채널 (32CH 통합: 채널 8~13, t.modbusReg 우선)
const dosingChannels = tanks.slice(0, 6).map((t, i) => {
    const ratio = dosingRatio[t.id] || 0;
    // 산/알칼리 모드 필터링 — id 표기 한글·영문·약어 모두 수용
    const isAcid   = t.id === '산' || t.id === 'acid'   || t.id === 'AC';
    const isAlkali = t.id === 'F' || t.id === 'alkali' || t.id === 'AL';
    let effectiveRatio = ratio;
    if (acidAlkaliMode === 'acid'   && isAlkali) effectiveRatio = 0;
    if (acidAlkaliMode === 'alkali' && isAcid)   effectiveRatio = 0;
    const volumeMl = BASE_VOLUME_ML * effectiveRatio / 100 * boost;
    return {
        channel: t.modbusReg ?? (8 + i),  // 32CH default: 8~13
        label: t.id,
        ratio: effectiveRatio,
        volumeMl,
        durationMs: volumeMl / (hw.dosingPulseUnit || 500) * 60000,
    };
});

// 중단 신호 체크 — abort-watcher 가 flow.set('manualAbortFlag', true) 또는 safetyStop
function shouldStop() {
    if (global.get('safetyStop')) return true;
    if (flow.get('manualAbortFlag')) {
        node.warn('manual abort 감지 — cleanup 진입');
        return true;
    }
    return false;
}

// cycle 시작 시 abort flag reset (이전 cycle 잔재 제거)
flow.set('manualAbortFlag', null);

// 시뮬레이터 모드일 때 시간 단축 (실 운영 50분/펌프 → 시뮬 1.5초/펌프)
const isSim = !!global.get('nutrientSimulator');
const simScale = isSim ? 0.0005 : 1.0;  // 1/2000 — 25L 펌프(50분) → 1.5초

// 도싱 실행 함수
function runDosing() {
    if (shouldStop()) return cleanup();
    updateCycle({ phase: 'dosing' });
    dosingChannels.forEach((d, i) => {
        if (d.volumeMl <= 0) return;
        // 펌프 ON
        sendRelay(d.channel, true, `도싱 ${d.label} ON`);
        // duration 후 OFF
        setTimeout(() => sendRelay(d.channel, false, `도싱 ${d.label} OFF`), d.durationMs * simScale);
    });
    // 모든 도싱 끝나면 다음 단계
    const maxDuration = Math.max(...dosingChannels.map(d => d.durationMs * simScale), 0);
    setTimeout(runMixing, maxDuration + 1000);
}

// === Phase 2: 교반 — hw.mixerOnSec 설정값 사용 ===
function runMixing() {
    if (shouldStop()) return cleanup();
    updateCycle({ phase: 'mixing' });
    const agitatorCh = hw.agitatorCh ?? 15;  // 32CH default
    sendRelay(agitatorCh, true, '교반기 ON');
    const mixSec = (hw.mixerOnSec ?? 30) * (isSim ? 0.1 : 1);  // sim: 30s → 3s
    setTimeout(() => {
        sendRelay(agitatorCh, false, `교반기 OFF (${mixSec}s)`);
        runStabilization();
    }, mixSec * 1000);
}

// === Phase 3: EC/pH 안정화 확인 (10초) ===
function runStabilization() {
    if (shouldStop()) return cleanup();
    updateCycle({ phase: 'stabilizing' });
    const stabSec = 10 * (isSim ? 0.2 : 1);  // sim: 10s → 2s
    setTimeout(() => {
        const lastTel = global.get('lastTelemetry');
        // 안정화 체크 (실 운영: 표준편차 0.05 이하 등)
        node.log(`안정화 OK: EC ${lastTel?.ec}, pH ${lastTel?.ph}`);
        runIrrigation();
    }, stabSec * 1000);
}

// === Phase 4: 관수 (메인펌프 + 밸브 순차) ===
function runIrrigation() {
    if (shouldStop()) return cleanup();
    updateCycle({ phase: 'irrigating' });
    const mainPumpCh = hw.mainPumpCh ?? 14;  // 32CH default
    global.set('mainPumpOn', true);
    sendRelay(mainPumpCh, true, '메인 펌프 ON');

    const valves = scenario.valves || [];
    const valveChannels = hw.valves || [];  // [{ id, name, ch }, ...]
    // 수동 작업이면 manualValves (밸브 id 배열) 만 순회, 아니면 0..valveCount-1
    const targetIndices = manualValves
        ? manualValves.map(id => id - 1).filter(i => i >= 0 && i < valveCount)
        : Array.from({ length: valveCount }, (_, i) => i);
    let k = 0;
    const runNext = () => {
        if (k >= targetIndices.length || shouldStop()) {
            global.set('mainPumpOn', false);
            sendRelay(mainPumpCh, false, '메인 펌프 OFF');
            return cleanup();
        }
        const i = targetIndices[k];
        const v = valves[i] || { duration: 600, volume: 150 };
        const channel = valveChannels[i]?.ch ?? (16 + i);
        const valveDur = v.duration * (isSim ? 0.01 : 1);  // sim: 600s → 6s/밸브

        updateCycle({ phase: 'irrigating', valveIdx: i + 1, suppliedL: (k + 1) * (v.volume / 1000) });
        sendRelay(channel, true, `밸브 ${i+1} ON (${valveDur}s)`);

        setTimeout(() => {
            sendRelay(channel, false, `밸브 ${i+1} OFF`);
            k++;
            setTimeout(runNext, 500); // 밸브 전환 0.5s 갭
        }, valveDur * 1000);
    };
    runNext();
}

// === Phase 5: 정리 ===
function cleanup() {
    // 상태 우선 정리 — 후속 abort-watcher polling 즉시 중단, 다음 cycle 발사 가능
    // 이전: sendBackend 먼저 후 state clear → 네트워크 실패 시 state stale.
    const aborted = global.get('safetyStop') || flow.get('manualAbortFlag');
    global.set('cycleInProgress', false);
    global.set('lastCycleAt', Date.now());
    global.set('currentCycle', null);
    flow.set('manualAbortFlag', null);

    updateCycle({ phase: 'done' });  // 마지막 telemetry — UI 표시용 (currentCycle null 이지만 publisher 가 별도 처리)

    // 수동 작업이면 targetIndices 기준, 아니면 전체 valveCount 기준 누적
    const usedIndices = manualValves
        ? manualValves.map(id => id - 1).filter(i => i >= 0 && i < valveCount)
        : Array.from({ length: valveCount }, (_, i) => i);
    const totalSupplied = usedIndices.reduce((s, i) =>
        s + ((scenario.valves || [])[i]?.volume || 0), 0) / 1000;

    // 누적 카운터 증가 (실패해도 state 는 이미 clear)
    sendBackend('POST', `/counters/increment`, {
        doseL: BASE_VOLUME_ML / 1000,
        irrigationL: totalSupplied,
        cycles: 1,
        runtimeMin: Math.floor((Date.now() - new Date(startedAt).getTime()) / 60000),
    });

    // 수동 작업이면 status 업데이트 — abort 면 aborted, 정상 완료면 completed
    if (manualJobId) {
        const finalStatus = aborted ? 'aborted' : 'completed';
        sendBackend('PUT', `/manual-jobs/${manualJobId}/status`, { status: finalStatus });
    }

    node.status({ fill: 'green', shape: 'dot', text: `✓ ${totalSupplied}L 공급 완료` });
}

// === 헬퍼 ===
function sendRelay(channel, on, label) {
    if (global.get('nutrientSimulator')) {
        node.log(`[SIM] ${label} (CH${channel} ${on ? 'ON' : 'OFF'})`);
        return;
    }
    // modbus-flex-write 호환: msg.payload = { value, fc, unitid, address, quantity }
    node.send([{
        payload: {
            value: on,
            fc: 5,           // FC5 = Write Single Coil
            unitid: 3,       // Unit-Id 3 = 32CH 통합 릴레이 (환경 0~7 + 양액 8~30)
            address: channel,
            quantity: 1,
        },
        label,
    }, null]);
}

function updateCycle(patch) {
    const cur = global.get('currentCycle') || {};
    const next = { ...cur, ...patch };
    global.set('currentCycle', next);
}

function sendBackend(method, path, body) {
    node.send([null, {
        url: `https://api.smartgreen.kr/internal/nutrient${path}`,
        method,
        headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
        },
        payload: body,
    }]);
}

// 시작!
runDosing();
return null;

// 양액 설정·시나리오·상태 fetcher — 5분 주기 inject
// 입력: timestamp (5분 inject)
// 출력: 3개 HTTP request 메시지 (config, scenarios, state)
//
// backend 에서 받아온 데이터는 응답 처리 노드에서 global 에 저장:
//   global.nutrientConfig  (탱크/밸브/경보/하드웨어)
//   global.activeScenario  (active=true 인 시나리오)
//   global.state           (mode + currentCycle 등)

// 기존 NR 패턴 — sensorApiKey + FARM_ID 환경변수 fallback
const farmId = global.get('FARM_ID') || 'farm_0001';
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';

const baseUrl = `https://api.smartgreen.kr/internal/nutrient`;
const headers = {
    'Content-Type': 'application/json',
    'x-api-key': apiKey,
};

const reqs = [
    { url: `${baseUrl}/config`,    method: 'GET', headers, _key: 'nutrientConfig' },
    { url: `${baseUrl}/scenarios`, method: 'GET', headers, _key: 'scenarios' },
    { url: `${baseUrl}/state`,     method: 'GET', headers, _key: 'state' },
];

node.status({ fill: 'blue', shape: 'dot', text: '⟳ 동기화 중' });

// NR multi-message single-output 패턴: 한 출력 포트에 여러 msg 발신
return [reqs.map(r => ({ ...r }))];

// ─────────────────────────────────────────
// 응답 처리 노드 (별도 function):
//   const key = msg._key;
//   const body = msg.payload;
//   if (body && body.success) {
//       if (key === 'nutrientConfig') {
//           global.set('nutrientConfig', body.data);
//       } else if (key === 'scenarios') {
//           const active = (body.data || []).find(s => s.active);
//           global.set('activeScenario', active || null);
//       } else if (key === 'state') {
//           global.set('state', body.data);
//       }
//   }
//   node.status({ fill: 'green', shape: 'dot', text: `✓ ${key}` });
//   return null;

const key = msg._key;
const body = msg.payload;
if (body && body.success) {
    if (key === 'nutrientConfig') {
        global.set('nutrientConfig', body.data);
    } else if (key === 'scenarios') {
        const active = (body.data || []).find(s => s.active);
        global.set('activeScenario', active || null);
    } else if (key === 'state') {
        global.set('state', body.data);
    }
}
node.status({ fill: 'green', shape: 'dot', text: '✓ ' + key });
return null;

const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';
msg.url = 'https://api.smartgreen.kr/internal/nutrient/manual-jobs/pending';
msg.method = 'GET';
msg.headers = { 'x-api-key': apiKey };
node.warn('[manual-poller] pre-fetch: ' + msg.url + ' apiKey=' + apiKey.slice(0,8));
return msg;

node.warn("[DBG] dispatch — cycleInProgress=" + global.get('cycleInProgress') + " safetyStop=" + global.get('safetyStop'));
node.warn("[manual-poller] dispatch: received");
// 수동 작업 polling — backend /internal/nutrient/manual-jobs/pending 응답 처리
//
// 입력: msg.payload = { success: true, data: [{...job, scenario}, ...] }
// backend 가 이미 mode != 'manual' 면 빈 배열로 응답 + scenario 객체 join 해서 전달.
// dispatch 는 cycleInProgress / safetyStop 만 검사.

if (global.get('cycleInProgress')) {
    node.status({ fill: 'blue', shape: 'dot', text: '사이클 진행 중' });
    return null;
}
if (global.get('safetyStop')) {
    node.status({ fill: 'red', shape: 'ring', text: '안전 정지' });
    return null;
}

const response = msg.payload || {};
if (!response.success || !Array.isArray(response.data)) {
    node.status({ fill: 'yellow', shape: 'ring', text: '응답 형식 오류' });
    return null;
}

const jobs = response.data;
if (jobs.length === 0) {
    const reason = response.reason || '대기 작업 없음';
    node.status({ fill: 'grey', shape: 'dot', text: reason });
    return null;
}

// 가장 오래된 due job 1개 (응답이 이미 scheduleAt 순)
const job = jobs[0];
const scenario = job.scenario;
if (!scenario) {
    node.warn(`scenario join 없음: scenarioId=${job.scenarioId}`);
    node.status({ fill: 'red', shape: 'ring', text: 'scenario 누락' });
    return null;
}

const payload = {
    scenarioId: scenario.id,
    scenario,
    triggeredAt: new Date().toISOString(),
    reason: 'manual',
    manualJobId: job.id,
    valves: Array.isArray(job.valves) ? job.valves : null,
    volumeML: job.volumeML ?? null,
};

node.status({ fill: 'green', shape: 'dot', text: `▶ ${job.id.slice(-6)} V[${(job.valves || []).join(',')}]` });
node.log(`수동 작업 발사: id=${job.id} valves=${JSON.stringify(job.valves)} volume=${job.volumeML || 'default'}`);

return { payload };

// manualJobId 가 currentCycle 에 있으면 backend job status fetch
const cc = global.get('currentCycle') || {};
if (!cc.manualJobId || !global.get('cycleInProgress')) {
    node.status({ fill: 'grey', shape: 'ring', text: 'idle' });
    return null;
}
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';
msg.url = `https://api.smartgreen.kr/internal/nutrient/manual-jobs/${cc.manualJobId}`;
msg.method = 'GET';
msg.headers = { 'x-api-key': apiKey };
return msg;

// 응답 검사 — status='aborted' 또는 'cancelled' 면 flow.manualAbortFlag 세팅.
// 단 fetched job.id 가 현재 cycle 의 manualJobId 와 일치할 때만 (stale 보호).
const resp = msg.payload || {};
if (!resp.success || !resp.data) {
    node.status({ fill: 'yellow', shape: 'ring', text: '응답 오류' });
    return null;
}
const job = resp.data;
const cc = global.get('currentCycle') || {};
if (cc.manualJobId !== job.id) {
    node.status({ fill: 'grey', shape: 'ring', text: 'stale id' });
    return null;
}
const status = job.status;
if (status === 'aborted' || status === 'cancelled') {
    flow.set('manualAbortFlag', true);
    node.warn(`abort signal: job=${job.id.slice(0,8)} status=${status}`);
    node.status({ fill: 'red', shape: 'dot', text: `🛑 ${status}` });
} else {
    node.status({ fill: 'green', shape: 'dot', text: `${status}` });
}
return null;

// 양액 직접 제어 — MQTT payload { channel, on } → Modbus FC5 single coil
// 안전 인터락: safetyStop 활성 시 거부.
// dead-man timer: ON 시 5분 후 자동 OFF 예약.

const payload = msg.payload || {};
const { channel, on } = payload;

if (typeof channel !== 'number' || channel < 0 || channel > 31) {
    node.warn('direct-relay: 잘못된 channel ' + channel);
    return null;
}
if (typeof on !== 'boolean') {
    node.warn('direct-relay: 잘못된 on ' + on);
    return null;
}

// 안전 인터락 — direct 제어도 안전 stop 적용
if (global.get('safetyStop')) {
    node.warn(`direct-relay 거부: safetyStop 활성 (CH${channel} ${on ? 'ON' : 'OFF'})`);
    node.status({ fill: 'red', shape: 'ring', text: '안전 정지 — 거부' });
    return null;
}

// 사이클 진행 중이면 거부 (자동/수동 cycle 과 충돌 방지)
if (global.get('cycleInProgress')) {
    node.warn(`direct-relay 거부: 사이클 진행 중 (CH${channel} ${on ? 'ON' : 'OFF'})`);
    node.status({ fill: 'yellow', shape: 'ring', text: '사이클 중 — 거부' });
    return null;
}

// dead-man timer — 5분 후 자동 OFF (해당 채널만)
const timers = global.get('directRelayTimers') || {};
if (timers[channel]) {
    clearTimeout(timers[channel]);
    delete timers[channel];
}
if (on) {
    timers[channel] = setTimeout(() => {
        node.warn(`dead-man timer: CH${channel} 5분 경과 자동 OFF`);
        node.send([{
            payload: {
                value: false,
                fc: 5, unitid: 3,
                address: channel,
                quantity: 1,
            },
            label: `[dead-man] CH${channel} OFF`,
        }, null]);
        // relayStatus 갱신
        const status = global.get('directRelayStatus') || {};
        status[channel] = false;
        global.set('directRelayStatus', status);
        const t = global.get('directRelayTimers') || {};
        delete t[channel];
        global.set('directRelayTimers', t);
    }, 5 * 60 * 1000);
}
global.set('directRelayTimers', timers);

// relayStatus 갱신 (UI 가 추후 사용)
const status = global.get('directRelayStatus') || {};
status[channel] = on;
global.set('directRelayStatus', status);

node.status({ fill: on ? 'green' : 'grey', shape: 'dot', text: `CH${channel} ${on ? 'ON' : 'OFF'}` });
node.log(`direct-relay: CH${channel} ${on ? 'ON' : 'OFF'}` + (on ? ' (5분 후 자동 OFF)' : ''));

// modbus-flex-write 호환
return {
    payload: {
        value: on,
        fc: 5,        // FC5 = Write Single Coil
        unitid: 3,    // Unit-Id 3 = 32CH 통합 릴레이
        address: channel,
        quantity: 1,
    },
    label: `direct CH${channel} ${on ? 'ON' : 'OFF'}`,
};

// ============================================================
// "표준 상태 반영" (fn_ks_status) — ks3267d 데몬이 POST /api/ks3267/status 로 밀어주는 상태를
// NR 전역에 반영한다. (KS X 3267 표준노드 탭, 2026-08-30 P3)
//
// 입력 msg.payload = { source:'ks3267d', unit, state }   (데몬 poll 결과)
//   state.kind === 'sensor'   → state.sensors[index] = { value, status, status_name }
//   state.kind === 'actuator' → state.devices[index] = { kind, n, opid, status, status_name, remain }
//
// 매핑 근거는 houseConfig:
//   센서:  house.sensors[].ks3267 = { unit, index }            → 값을 global.ks3267Readings[sensorId] 로
//   구동기: house.devices[].modbus = { protocol:'ks3267', unit, kind:'switch'|'opener', n }
//          → deviceStates['house_0001:fan1'] 갱신 (정규키, dkey)
// 원본 상태는 global.ks3267State[unit] 에 그대로 보관 (진단 UI·남은시간 표시용).
// ============================================================
const body = msg.payload || {};
const st = body.state || {};
const unit = Number(body.unit);
if (!unit || !st.kind) {
    msg.statusCode = 400; msg.payload = { success: false, error: 'unit/state 필요' };
    return msg;
}

const config = global.get('houseConfig') || {};
const houses = config.houses || [];
const dkey = global.get('dkey') || function (h, dv) { return (h || 'house_0001') + ':' + dv; };

// 원본 보관 (진단·UI)
const all = global.get('ks3267State') || {};
all[unit] = Object.assign({ receivedAt: new Date().toISOString() }, st);
global.set('ks3267State', all);

let sensorsMapped = 0, devicesMapped = 0;

if (st.kind === 'sensor') {
    // 센서 → 수집 파이프라인(③)이 읽는 전역. TTL 은 ③ 쪽에서 t 로 판단한다.
    const cur = global.get('ks3267Readings') || { values: {}, t: 0 };
    const values = Object.assign({}, cur.values || {});
    for (const house of houses) {
        for (const s of (house.sensors || [])) {
            const k = s.ks3267;
            if (!k || Number(k.unit) !== unit) continue;
            const r = (st.sensors || {})[String(k.index)] || (st.sensors || {})[k.index];
            if (!r || typeof r.value !== 'number') continue;
            if (r.status >= 100) {
                // NEED_REPLACE(101)/CALIBRATION(102)/CHECK(103): 값은 있으나 신뢰 낮음 — 기록은 남기고 값은 넣지 않는다
                node.warn('⚠️ 표준 센서 ' + s.sensorId + ' 상태 ' + (r.status_name || r.status) + ' — 값 생략');
                continue;
            }
            values[s.sensorId] = r.value;
            sensorsMapped++;
        }
    }
    global.set('ks3267Readings', { values: values, t: Date.now(), unit: unit });
} else if (st.kind === 'actuator') {
    const states = global.get('deviceStates') || {};
    for (const house of houses) {
        for (const d of (house.devices || [])) {
            const m = d.modbus;
            if (!m || m.protocol !== 'ks3267' || Number(m.unit) !== unit) continue;
            const dev = Object.values(st.devices || {}).find(x => x.kind === m.kind && Number(x.n) === Number(m.n));
            if (!dev) continue;
            const DK = dkey(house.houseId, d.deviceId);
            const code = Number(dev.status);
            if (m.kind === 'switch') {
                states[DK] = (code === 201) ? 'on' : (code === 0 ? 'off' : states[DK]);
            } else {
                // 개폐형: 301 여는 중 → open, 302 닫는 중 → closed, 0 READY 는 명령 경로가 정한 상태 유지
                if (code === 301) states[DK] = 'open';
                else if (code === 302) states[DK] = 'closed';
            }
            devicesMapped++;
        }
    }
    global.set('deviceStates', states);
}

node.status({ fill: 'green', shape: 'dot', text: 'unit ' + unit + ' ' + st.kind + ' (센서 ' + sensorsMapped + ' / 장치 ' + devicesMapped + ')' });
msg.statusCode = 200;
msg.payload = { success: true, unit: unit, kind: st.kind, sensorsMapped: sensorsMapped, devicesMapped: devicesMapped };
return msg;

// ============================================================
// "표준 명령 조립" (fn_ks_command) — execute_control 의 3번 출력(link)으로 넘어온 제어를
// ks3267d 데몬 REST 명령으로 바꾼다. (KS X 3267 표준노드 탭, 2026-08-30 P3)
//
// 입력 msg.control = { houseId, deviceId, command, duration, modbus:{ protocol:'ks3267', unit, kind, n } }
// 우리 명령 → 표준 명령 (6.3.3 / 6.3.4, 레벨1):
//   스위치: on → ON(201) / off → OFF(0) / on + duration>0 → TIMED_ON(202, 초)
//   개폐기: open → OPEN(301) / close → CLOSE(302) / stop → STOP(0)
//           open + duration>0 → TIMED_OPEN(303) / close + duration>0 → TIMED_CLOSE(304)
// 레벨2(SET_POSITION 등)는 만들지 않는다 — 데몬도 로컬에서 거부한다 (스코프 선언 일치).
// ============================================================
const ctrl = msg.control || {};
const m = ctrl.modbus || {};
const cmd = String(ctrl.command || '').toLowerCase();
const dur = Number(ctrl.duration || 0);

if (m.protocol !== 'ks3267' || !m.unit || !m.kind || !m.n) {
    node.error('표준 명령 조립: modbus 프로필 불완전 ' + JSON.stringify(m), msg);
    return null;
}

let op = null;
if (m.kind === 'switch') {
    if (cmd === 'on' || cmd === 'open') op = dur > 0 ? 'timed_on' : 'on';
    else if (cmd === 'off' || cmd === 'close' || cmd === 'stop') op = 'off';
} else if (m.kind === 'opener') {
    if (cmd === 'open') op = dur > 0 ? 'timed_open' : 'open';
    else if (cmd === 'close') op = dur > 0 ? 'timed_close' : 'close';
    else if (cmd === 'stop') op = 'stop';
}
if (!op) {
    node.error('표준 명령 조립: ' + m.kind + ' 에 ' + cmd + ' 는 대응 명령 없음', msg);
    return null;
}

const api = env.get('KS3267_API') || 'http://127.0.0.1:3002';
msg.url = api + '/command';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { unit: Number(m.unit), kind: m.kind, n: Number(m.n), op: op, seconds: dur > 0 ? Math.round(dur) : 0 };
msg.requestTimeout = 5000;
msg._ksControl = ctrl;   // 결과 처리에서 사용

node.status({ fill: 'blue', shape: 'dot', text: ctrl.deviceId + ' → ' + op + (dur > 0 ? ' ' + Math.round(dur) + 's' : '') });
node.warn('📤 KS3267 명령: unit ' + m.unit + ' ' + m.kind + m.n + ' ' + op + (dur > 0 ? ' (' + Math.round(dur) + '초)' : '') + ' [' + ctrl.deviceId + ']');
return msg;

// ============================================================
// "표준 명령 결과" (fn_ks_result) — 데몬 응답을 상태·이력에 반영. (KS X 3267 표준노드 탭, P3)
//
// 입력: msg.payload = 데몬 /command 응답 { ok, accepted, opid, status, status_name, remain, error?, exception? }
//       msg._ksControl = 원 제어 정보
// 출력 1: 제어 이력(서버 POST /internal/control-log) — 성공/거부 모두 기록 (fix ⑧ 과 같은 원칙)
// 출력 2: (예비) 상태 발행
// ============================================================
const r = (typeof msg.payload === 'object' && msg.payload) || {};
const ctrl = msg._ksControl || {};
const m = ctrl.modbus || {};
const dkey = global.get('dkey') || function (h, dv) { return (h || 'house_0001') + ':' + dv; };
const DK = dkey(ctrl.houseId, ctrl.deviceId);

const ok = !!(r.ok && r.accepted !== false);
if (ok) {
    const states = global.get('deviceStates') || {};
    const c = String(ctrl.command || '').toLowerCase();
    if (m.kind === 'switch') states[DK] = (c === 'off' || c === 'close' || c === 'stop') ? 'off' : 'on';
    else states[DK] = c === 'open' ? 'open' : (c === 'close' ? 'closed' : 'idle');
    global.set('deviceStates', states);
    node.status({ fill: 'green', shape: 'dot', text: ctrl.deviceId + ' ' + (r.status_name || '') + (r.remain ? ' ' + r.remain + 's' : '') + ' opid ' + r.opid });
    node.warn('✅ KS3267 ' + ctrl.deviceId + ' ' + ctrl.command + ' → ' + (r.status_name || r.status) + ' (opid ' + r.opid + (r.remain ? ', 남은 ' + r.remain + 's' : '') + ')');
} else {
    node.status({ fill: 'red', shape: 'ring', text: ctrl.deviceId + ' 실패: ' + (r.error || msg.statusCode) });
    node.warn('❌ KS3267 ' + ctrl.deviceId + ' ' + ctrl.command + ' 실패: ' + (r.error || ('HTTP ' + msg.statusCode)) + (r.exception ? ' (예외 0x0' + r.exception + ')' : ''));
}

// 제어 이력 — 서버 (거부도 기록: "왜 안 됐지" 추적)
const pcServer = global.get('pcServerUrl') || 'https://api.smartgreen.kr';
const logMsg = {
    method: 'POST',
    url: pcServer + '/internal/control-log',
    headers: { 'Content-Type': 'application/json', 'x-api-key': env.get('SENSOR_API_KEY') || global.get('sensorApiKey') || '' },
    payload: {
        farmId: global.get('farmId') || env.get('FARM_ID') || 'farm_0001',
        houseId: ctrl.houseId || 'house_0001',
        deviceId: ctrl.deviceId,
        deviceType: ctrl.deviceType || (m.kind === 'opener' ? 'window' : 'relay'),
        deviceName: ctrl.deviceName || ctrl.deviceId,
        command: ctrl.command,
        success: ok,
        operator: ctrl.operator || 'unknown',
        reason: ok ? ('KS X 3267 ' + (r.status_name || '') + ' opid ' + r.opid) : ('KS X 3267 실패: ' + (r.error || msg.statusCode)),
        requestId: ctrl.requestId || null,
        metadata: { protocol: 'ks3267', unit: m.unit, kind: m.kind, n: m.n, opid: r.opid, status: r.status, remain: r.remain, exception: r.exception || null }
    }
};
return [logMsg, null];

// ============================================================
// "데몬 프록시" (fn_ks_proxy) — GET /api/ks3267/:action 을 127.0.0.1:3002 데몬으로 넘긴다.
// (KS X 3267 표준노드 탭, P3). 설정 UI 의 탐색·상태·프레임 조회가 백엔드 → 여기 → 데몬 순으로 온다.
// httpNodeMiddleware 가 /api/* 인증(키오스크 루프백 또는 농장 키)을 이미 적용한다.
// 읽기 전용 액션만 — 제어는 정규 경로(execute_control)로만.
// ============================================================
const ALLOWED = { discover: 1, nodes: 1, status: 1, frames: 1, events: 1, health: 1 };
const action = String((msg.req && msg.req.params && msg.req.params.action) || '');
if (!ALLOWED[action]) {
    msg.statusCode = 400;
    msg.payload = { success: false, error: '허용되지 않는 액션: ' + action };
    return [null, msg];   // 출력 2 = 즉시 응답
}
const q = (msg.req && msg.req.query) || {};
const qs = Object.keys(q).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(q[k])).join('&');
const api = env.get('KS3267_API') || 'http://127.0.0.1:3002';
msg.url = api + '/' + action + (qs ? '?' + qs : '');
msg.method = 'GET';
msg.requestTimeout = 8000;
msg._ksAction = action;
return [msg, null];   // 출력 1 = http request 로

// 데몬 응답을 그대로 돌려주되, 연결 실패는 502 로
if (typeof msg.payload !== 'object' || msg.payload === null) {
    msg.statusCode = 502;
    msg.payload = { success: false, error: 'ks3267d 데몬 응답 없음 (pm2 ks3267d 확인)', detail: String(msg.payload).slice(0, 200) };
} else {
    msg.statusCode = msg.statusCode || 200;
}
return msg;

// ============================================================
// "표준 구동기 1분 스냅샷" (fn_ks_snapshot) — KS X 3267 표준노드 탭 (2026-08-30, 116 검정)
// inject(60초) → 이 함수 → http request(서버 POST /internal/actuator-status) → "스냅샷 전송 결과"
//
// 왜: KOAT 116 「통합제어기」는 구동기 상태정보를 1분 단위로 저장·조회·추출하고 24시간 손실률(≤3%)을 잰다.
//      드라이버(ks3267d)는 상태 변화 + 60초 하트비트로 NR 전역 ks3267State 를 갱신한다.
// 원칙: 값을 지어내지 않는다 — 3분 넘게 갱신 없는 노드(데몬 중단·버스 단선)는 행을 만들지 않는다 (= 손실로 드러난다).
//       전송 실패분은 flow 큐에 남겨 다음 분에 함께 재전송 (서버는 PK 로 중복 무시 → 멱등). 큐 상한 20,000행.
// ============================================================
const config = global.get('houseConfig') || {};
const all = global.get('ks3267State') || {};
const now = Date.now();
const STALE_MS = 180000;
const minuteIso = new Date(Math.floor(now / 60000) * 60000).toISOString();

const rows = [];
for (const house of (config.houses || [])) {
    for (const d of (house.devices || [])) {
        const m = d.modbus;
        if (!m || m.protocol !== 'ks3267') continue;
        const st = all[m.unit] || all[String(m.unit)];
        if (!st || !st.devices) continue;
        const rec = Date.parse(st.receivedAt || '') || 0;
        if (now - rec > STALE_MS) continue;                       // 낡은 상태는 기록하지 않는다
        const dev = Object.values(st.devices).find(x => x.kind === m.kind && Number(x.n) === Number(m.n));
        if (!dev) continue;
        rows.push({
            timestamp: minuteIso, houseId: house.houseId, deviceId: d.deviceId,
            unit: Number(m.unit), kind: m.kind, n: Number(m.n),
            status: Number(dev.status), statusName: dev.status_name || null,
            remain: Number(dev.remain) || 0, opid: Number(dev.opid) || 0
        });
    }
}

let queue = (flow.get('ksSnapshotQueue') || []).concat(rows);
if (queue.length > 20000) queue = queue.slice(queue.length - 20000);
flow.set('ksSnapshotQueue', queue);

if (queue.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: '표준 장치 없음/상태 낡음 — 기록 없음' });
    return null;
}

const BATCH = 5000;
const pcServer = global.get('pcServerUrl') || 'https://api.smartgreen.kr';
msg.method = 'POST';
msg.url = pcServer + '/internal/actuator-status';
msg.headers = { 'Content-Type': 'application/json', 'x-api-key': env.get('SENSOR_API_KEY') || global.get('sensorApiKey') || '' };
msg.payload = { farmId: global.get('farmId') || env.get('FARM_ID') || 'farm_0001', rows: queue.slice(0, BATCH) };
msg.requestTimeout = 10000;
msg._sent = Math.min(queue.length, BATCH);
node.status({ fill: 'blue', shape: 'dot', text: '전송 ' + msg._sent + '행 (이번 분 ' + rows.length + ')' });
return msg;

// ============================================================
// "스냅샷 전송 결과" (fn_ks_snapshot_result) — 성공하면 보낸 만큼 큐에서 지우고, 실패하면 남겨 다음 분에 재전송.
// (KS X 3267 표준노드 탭, 2026-08-30) http request 는 "2xx 아닌 응답만 Catch" 해제 상태여야 여기로 온다.
// ============================================================
const queue = flow.get('ksSnapshotQueue') || [];
const sent = Number(msg._sent) || 0;
const p = (typeof msg.payload === 'object' && msg.payload) || {};
const ok = msg.statusCode === 200 && p.success === true;

if (ok) {
    const rest = queue.slice(sent);
    flow.set('ksSnapshotQueue', rest);
    node.status({ fill: 'green', shape: 'dot', text: '저장 ' + (p.inserted ?? '?') + '/' + (p.received ?? sent) + (rest.length ? ' · 대기 ' + rest.length : '') });
} else {
    node.warn('⚠️ 구동기 스냅샷 전송 실패 (HTTP ' + msg.statusCode + '): ' + (p.error || String(msg.payload).slice(0, 120)) + ' — 큐 ' + queue.length + '행 보존, 다음 분 재전송');
    node.status({ fill: 'red', shape: 'ring', text: '전송 실패 · 큐 ' + queue.length });
}
return null;
